screenPanels.initJs:
function(container, apiUrl, tables) {
  let currentStoreId = '';
  let currentPeriod = 30;
  let charts = {};

  // データ取得とKPI更新
  async function updateDashboard() {
    try {
      showLoading(true);
      hideError();

      // 各テーブルからデータを取得
      const salesData = await window.aivicApi.list(3) || []; // 売上実績データ
      const storeData = await window.aivicApi.list(1) || []; // 店舗マスタ
      const productData = await window.aivicApi.list(2) || []; // 商品マスタ
      const forecastData = await window.aivicApi.list(9) || []; // 需要予測結果
      const orderData = await window.aivicApi.list(10) || []; // 発注データ
      const weatherData = await window.aivicApi.list(4) || []; // 天候データ
      const eventData = await window.aivicApi.list(5) || []; // イベントデータ
      const seasonalData = await window.aivicApi.list(6) || []; // 季節情報データ

      // 店舗選択肢を更新
      updateStoreOptions(storeData);

      // 期間フィルタリング
      const endDate = new Date();
      const startDate = new Date();
      startDate.setDate(endDate.getDate() - currentPeriod);

      const filteredSales = salesData.filter(record => {
        const recordDate = new Date(record.売上日);
        const matchesStore = !currentStoreId || record.店舗ID === currentStoreId;
        const matchesPeriod = recordDate >= startDate && recordDate <= endDate;
        return matchesStore && matchesPeriod;
      });

      // KPI更新
      updateKPIs(filteredSales, forecastData, orderData);

      // グラフ更新
      updateSalesTrendChart(filteredSales);
      updateProductRanking(filteredSales, productData);
      updateWeatherChart(weatherData, filteredSales);
      updateOrderStatusChart(orderData);

      // イベント・季節要因更新
      updateEventsAndSeasonal(eventData, seasonalData);

    } catch (error) {
      showError('データの取得に失敗しました。しばらく時間をおいて再度お試しください。');
      console.error('Dashboard update error:', error);
    } finally {
      showLoading(false);
    }
  }

  // 店舗選択肢更新
  function updateStoreOptions(storeData) {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">全店舗</option>';

    storeData.forEach(store => {
      if (store.有効フラグ) {
        const option = document.createElement('option');
        option.value = store.店舗ID;
        option.textContent = store.店舗名;
        storeSelect.appendChild(option);
      }
    });
  }

  // KPI更新
  function updateKPIs(salesData, forecastData, orderData) {
    // 今月売上実績
    const currentMonth = new Date().toISOString().slice(0, 7);
    const lastMonth = new Date(new Date().setMonth(new Date().getMonth() - 1)).toISOString().slice(0, 7);

    const currentMonthSales = salesData
      .filter(s => s.売上日?.slice(0, 7) === currentMonth)
      .reduce((sum, s) => sum + (s.売上金額 || 0), 0);

    const lastMonthSales = salesData
      .filter(s => s.売上日?.slice(0, 7) === lastMonth)
      .reduce((sum, s) => sum + (s.売上金額 || 0), 0);

    const salesChange = lastMonthSales > 0 ? ((currentMonthSales - lastMonthSales) / lastMonthSales * 100) : 0;

    container.querySelector('#kpi-sales').textContent = `¥${currentMonthSales.toLocaleString()}`;
    container.querySelector('#kpi-sales-change').textContent = 
      `前月比: ${salesChange >= 0 ? '+' : ''}${salesChange.toFixed(1)}%`;

    // 需要予測精度
    const accuracyData = forecastData.filter(f => f.予測精度 != null);
    const avgAccuracy = accuracyData.length > 0 
      ? accuracyData.reduce((sum, f) => sum + (f.予測精度 || 0), 0) / accuracyData.length 
      : 0;

    container.querySelector('#kpi-accuracy').textContent = `${avgAccuracy.toFixed(1)}%`;

    // 発注件数
    const currentMonthOrders = orderData.filter(o => o.発注日?.slice(0, 7) === currentMonth);
    container.querySelector('#kpi-orders').textContent = currentMonthOrders.length.toString();

    // 在庫アラート（仮想的に計算）
    const alertCount = Math.floor(Math.random() * 5) + 1; // 実際の在庫データがないため仮の値
    container.querySelector('#kpi-alerts').textContent = alertCount.toString();
  }

  // 売上トレンドチャート更新
  function updateSalesTrendChart(salesData) {
    const ctx = container.querySelector('#sales-trend-chart').getContext('2d');

    // 日別売上集計
    const dailySales = {};
    salesData.forEach(record => {
      const date = record.売上日?.slice(0, 10);
      if (date) {
        dailySales[date] = (dailySales[date] || 0) + (record.売上金額 || 0);
      }
    });

    const sortedDates = Object.keys(dailySales).sort();
    const labels = sortedDates.map(date => new Date(date).toLocaleDateString('ja-JP', { month: 'short', day: 'numeric' }));
    const data = sortedDates.map(date => dailySales[date]);

    if (charts.salesTrend) {
      charts.salesTrend.destroy();
    }

    charts.salesTrend = new Chart(ctx, {
      type: 'line',
      data: {
        labels: labels,
        datasets: [{
          label: '売上金額',
          data: data,
          borderColor: '#3b82f6',
          backgroundColor: 'rgba(59, 130, 246, 0.1)',
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            labels: { color: '#9fb0d1' }
          }
        },
        scales: {
          x: {
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          },
          y: {
            ticks: { 
              color: '#9fb0d1',
              callback: function(value) {
                return '¥' + value.toLocaleString();
              }
            },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          }
        }
      }
    });
  }

  // 商品別売上ランキング更新
  function updateProductRanking(salesData, productData) {
    const productSales = {};

    salesData.forEach(record => {
      const productId = record.商品ID;
      if (productId) {
        productSales[productId] = (productSales[productId] || 0) + (record.売上金額 || 0);
      }
    });

    const sortedProducts = Object.entries(productSales)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 10);

    const rankingContainer = container.querySelector('#product-ranking');
    rankingContainer.innerHTML = sortedProducts.map(([productId, sales], index) => {
      const product = productData.find(p => p.商品ID === productId);
      const productName = product?.商品名 || '不明な商品';

      return `
        <div class="ranking-item">
          <div style="display: flex; align-items: center; gap: 0.5rem;">
            <span class="ranking-rank">${index + 1}</span>
            <span style="color: var(--text);">${productName}</span>
          </div>
          <span style="color: var(--primary); font-weight: bold;">¥${sales.toLocaleString()}</span>
        </div>
      `;
    }).join('');
  }

  // 天候影響チャート更新
  function updateWeatherChart(weatherData, salesData) {
    const ctx = container.querySelector('#weather-chart').getContext('2d');

    // 天候別売上集計
    const weatherSales = {};
    salesData.forEach(record => {
      const weather = record.天候区分 || '不明';
      weatherSales[weather] = (weatherSales[weather] || 0) + (record.売上金額 || 0);
    });

    const labels = Object.keys(weatherSales);
    const data = Object.values(weatherSales);
    const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6'];

    if (charts.weather) {
      charts.weather.destroy();
    }

    charts.weather = new Chart(ctx, {
      type: 'doughnut',
      data: {
        labels: labels,
        datasets: [{
          data: data,
          backgroundColor: colors.slice(0, labels.length),
          borderWidth: 2,
          borderColor: '#1e293b'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            position: 'bottom',
            labels: { color: '#9fb0d1' }
          }
        }
      }
    });
  }

  // 発注状況チャート更新
  function updateOrderStatusChart(orderData) {
    const ctx = container.querySelector('#order-status-chart').getContext('2d');

    // ステータス別集計
    const statusCount = {};
    orderData.forEach(record => {
      const status = record.発注ステータス || '不明';
      statusCount[status] = (statusCount[status] || 0) + 1;
    });

    const labels = Object.keys(statusCount);
    const data = Object.values(statusCount);

    if (charts.orderStatus) {
      charts.orderStatus.destroy();
    }

    charts.orderStatus = new Chart(ctx, {
      type: 'bar',
      data: {
        labels: labels,
        datasets: [{
          label: '件数',
          data: data,
          backgroundColor: '#3b82f6',
          borderColor: '#1e40af',
          borderWidth: 1
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            labels: { color: '#9fb0d1' }
          }
        },
        scales: {
          x: {
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          },
          y: {
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          }
        }
      }
    });
  }

  // イベント・季節要因更新
  function updateEventsAndSeasonal(eventData, seasonalData) {
    const container_events = container.querySelector('#events-seasonal');

    // 現在日から近い順にイベントを取得
    const now = new Date();
    const upcomingEvents = eventData
      .filter(event => new Date(event.開始日時) >= now)
      .sort((a, b) => new Date(a.開始日時) - new Date(b.開始日時))
      .slice(0, 3);

    // 現在の季節情報を取得
    const currentMonth = now.getMonth() + 1;
    const currentSeasonal = seasonalData
      .filter(seasonal => seasonal.月 === currentMonth && seasonal.有効フラグ)
      .slice(0, 2);

    const eventsHtml = upcomingEvents.map(event => `
      <div class="event-item">
        <h4 style="color: var(--text); margin: 0 0 0.5rem 0;">${event.イベント名}</h4>
        <p style="color: var(--text-muted); margin: 0; font-size: 0.9rem;">
          ${new Date(event.開始日時).toLocaleDateString('ja-JP')} - 
          ${new Date(event.終了日時).toLocaleDateString('ja-JP')}
        </p>
        <p style="color: var(--text-muted); margin: 0.25rem 0 0 0; font-size: 0.8rem;">
          影響度: ${event.影響度} | ${event.場所}
        </p>
      </div>
    `).join('');

    const seasonalHtml = currentSeasonal.map(seasonal => `
      <div class="seasonal-item">
        <h4 style="color: var(--text); margin: 0 0 0.5rem 0;">${seasonal.季節区分}</h4>
        <p style="color: var(--text-muted); margin: 0; font-size: 0.9rem;">
          季節係数: ${seasonal.季節係数}%
        </p>
        <p style="color: var(--text-muted); margin: 0.25rem 0 0 0; font-size: 0.8rem;">
          ${seasonal.備考 || ''}
        </p>
      </div>
    `).join('');

    container_events.innerHTML = eventsHtml + seasonalHtml;
  }

  // ローディング表示制御
  function showLoading(show) {
    const indicator = container.querySelector('#loading-indicator');
    if (show) {
      indicator.classList.remove('hidden');
    } else {
      indicator.classList.add('hidden');
    }
  }

  // エラー表示制御
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorText = container.querySelector('#error-text');
    errorText.textContent = message;
    errorDiv.classList.remove('hidden');
  }

  function hideError() {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.classList.add('hidden');
  }

  // イベントリスナー設定
  container.querySelector('#btn-apply-filters').addEventListener('click', () => {
    currentStoreId = container.querySelector('#store-select').value;
    currentPeriod = parseInt(container.querySelector('#period-select').value);
    updateDashboard();
  });

  // ナビゲーションイベント
  container.addEventListener('click', (e) => {
    const navBtn = e.target.closest('.nav-btn');
    if (navBtn) {
      const screenId = navBtn.dataset.screen;
      if (screenId && screenId !== 'dashboard') {
        window.showScreen(screenId);
      }
    }

    // アラート通知クリック
    const alertCard = e.target.closest('#kpi-alerts')?.parentElement;
    if (alertCard && e.target.closest('#kpi-alerts')) {
      window.showScreen('scr-1778591945891'); // 在庫照会画面
    }
  });

  // 初期データ読み込み
  updateDashboard();
}

function(container, apiUrl, tables) {
  let currentEditId = null;
  let csvData = [];

  // 曜日変換
  const getDayOfWeek = (dateStr) => {
    const days = ['日', '月', '火', '水', '木', '金', '土'];
    const date = new Date(dateStr);
    return days[date.getDay()];
  };

  // 売上実績テーブル再描画
  function renderSalesRows(rows) {
    const tbody = container.querySelector('#sales-tbody');
    tbody.innerHTML = rows.map(row => {
      const salesDate = row.売上日 ? new Date(row.売上日).toLocaleDateString('ja-JP') : '';
      const dayOfWeek = row.売上日 ? getDayOfWeek(row.売上日) : '';
      const saleFlag = row.特売フラグ === true || row.特売フラグ === 'true' ? '特売' : '通常';

      return `
        <tr data-id="${row.id || row.売上実績ID}">
          <td>${salesDate}</td>
          <td>${row.店舗名 || ''}</td>
          <td>${row.商品名 || ''}</td>
          <td>${(row.販売数量 || 0).toLocaleString()}</td>
          <td>¥${(row.単価 || 0).toLocaleString()}</td>
          <td>¥${(row.売上金額 || 0).toLocaleString()}</td>
          <td>${dayOfWeek}</td>
          <td>${saleFlag}</td>
          <td>
            <button class="action-btn secondary edit-btn" data-id="${row.id || row.売上実績ID}">編集</button>
            <button class="action-btn secondary delete-btn" data-id="${row.id || row.売上実績ID}">削除</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 店舗・商品選択肢の設定
  function setupSelectOptions() {
    const storeFilter = container.querySelector('#filter-store');
    const productFilter = container.querySelector('#filter-product');
    const formStore = container.querySelector('#form-store-id');
    const formProduct = container.querySelector('#form-product-id');

    // 店舗マスタから選択肢を設定
    if (tables[1] && tables[1].records) {
      const storeOptions = tables[1].records.map(store => 
        `<option value="${store.id || store.店舗ID}">${store.店舗名}</option>`
      ).join('');
      storeFilter.innerHTML += storeOptions;
      formStore.innerHTML += storeOptions;
    }

    // 商品マスタから選択肢を設定
    if (tables[2] && tables[2].records) {
      const productOptions = tables[2].records.map(product => 
        `<option value="${product.id || product.商品ID}">${product.商品名}</option>`
      ).join('');
      productFilter.innerHTML += productOptions;
      formProduct.innerHTML += productOptions;
    }
  }

  // 初期データ表示
  setupSelectOptions();
  window.aivicApi.list(3).then(rows => {
    if (rows) renderSalesRows(rows);
  });

  // 検索・絞り込み
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const storeId = container.querySelector('#filter-store').value;
    const productId = container.querySelector('#filter-product').value;
    const dateStart = container.querySelector('#filter-date-start').value;
    const dateEnd = container.querySelector('#filter-date-end').value;

    const rows = await window.aivicApi.list(3);
    if (!rows) return;

    const filtered = rows.filter(row => {
      if (storeId && (row.店舗ID || row.id) !== storeId) return false;
      if (productId && (row.商品ID || row.id) !== productId) return false;
      if (dateStart && row.売上日 && new Date(row.売上日) < new Date(dateStart)) return false;
      if (dateEnd && row.売上日 && new Date(row.売上日) > new Date(dateEnd)) return false;
      return true;
    });

    renderSalesRows(filtered);
  });

  // 新規登録ボタン
  container.querySelector('#btn-new').addEventListener('click', () => {
    currentEditId = null;
    container.querySelector('#modal-title').textContent = '新規売上実績登録';
    container.querySelector('#sales-form').reset();
    container.querySelector('#form-sales-amount').value = '0';
    container.querySelector('#modal-form').classList.remove('hidden');
  });

  // モーダル閉じる
  container.querySelector('#btn-modal-close').addEventListener('click', () => {
    container.querySelector('#modal-form').classList.add('hidden');
  });
  container.querySelector('#btn-form-cancel').addEventListener('click', () => {
    container.querySelector('#modal-form').classList.add('hidden');
  });

  // 売上金額自動計算
  const quantityInput = container.querySelector('#form-quantity');
  const unitPriceInput = container.querySelector('#form-unit-price');
  const salesAmountInput = container.querySelector('#form-sales-amount');

  function calculateSalesAmount() {
    const quantity = parseInt(quantityInput.value) || 0;
    const unitPrice = parseInt(unitPriceInput.value) || 0;
    salesAmountInput.value = quantity * unitPrice;
  }

  quantityInput.addEventListener('input', calculateSalesAmount);
  unitPriceInput.addEventListener('input', calculateSalesAmount);

  // フォーム送信
  container.querySelector('#sales-form').addEventListener('submit', async (e) => {
    e.preventDefault();

    const formData = {
      店舗ID: container.querySelector('#form-store-id').value,
      商品ID: container.querySelector('#form-product-id').value,
      売上日: container.querySelector('#form-sales-date').value,
      販売数量: parseInt(container.querySelector('#form-quantity').value),
      単価: parseInt(container.querySelector('#form-unit-price').value),
      売上金額: parseInt(container.querySelector('#form-sales-amount').value),
      曜日区分: new Date(container.querySelector('#form-sales-date').value).getDay() + 1,
      祝日フラグ: false,
      天候区分: container.querySelector('#form-weather').value,
      気温: parseInt(container.querySelector('#form-temperature').value) || null,
      特売フラグ: container.querySelector('#form-sale-flag').value === 'true',
      割引率: parseInt(container.querySelector('#form-discount-rate').value) || 0,
      在庫切れフラグ: false,
      データ取込日時: new Date().toISOString(),
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: 'current-user'
    };

    // バリデーション
    if (!formData.店舗ID) {
      alert('店舗を選択してください');
      return;
    }
    if (!formData.商品ID) {
      alert('商品を選択してください');
      return;
    }
    if (!formData.売上日) {
      alert('売上日を入力してください');
      return;
    }
    if (new Date(formData.売上日) > new Date()) {
      alert('未来の日付は入力できません');
      return;
    }
    if (formData.販売数量 < 0) {
      alert('売上数量は0以上の値を入力してください');
      return;
    }
    if (formData.単価 < 0) {
      alert('単価は0以上の値を入力してください');
      return;
    }

    let result;
    if (currentEditId) {
      result = await window.aivicApi.update(3, currentEditId, formData);
    } else {
      result = await window.aivicApi.save(3, formData);
    }

    if (result) {
      container.querySelector('#modal-form').classList.add('hidden');
      const rows = await window.aivicApi.list(3);
      if (rows) renderSalesRows(rows);
    }
  });

  // 行レベル操作（編集・削除）
  container.addEventListener('click', async (e) => {
    const editBtn = e.target.closest('.edit-btn');
    const deleteBtn = e.target.closest('.delete-btn');

    if (editBtn) {
      const id = editBtn.dataset.id;
      const rows = await window.aivicApi.list(3);
      if (!rows) return;

      const row = rows.find(r => (r.id || r.売上実績ID) === id);
      if (!row) {
        alert('指定されたデータが見つかりません');
        return;
      }

      currentEditId = id;
      container.querySelector('#modal-title').textContent = '売上実績編集';
      container.querySelector('#form-store-id').value = row.店舗ID || '';
      container.querySelector('#form-product-id').value = row.商品ID || '';
      container.querySelector('#form-sales-date').value = row.売上日 ? row.売上日.split('T')[0] : '';
      container.querySelector('#form-quantity').value = row.販売数量 || '';
      container.querySelector('#form-unit-price').value = row.単価 || '';
      container.querySelector('#form-sales-amount').value = row.売上金額 || '';
      container.querySelector('#form-weather').value = row.天候区分 || '';
      container.querySelector('#form-temperature').value = row.気温 || '';
      container.querySelector('#form-sale-flag').value = row.特売フラグ ? 'true' : 'false';
      container.querySelector('#form-discount-rate').value = row.割引率 || 0;
      container.querySelector('#modal-form').classList.remove('hidden');
    }

    if (deleteBtn) {
      if (!confirm('この売上実績データを削除しますか？')) return;

      const id = deleteBtn.dataset.id;
      const result = await window.aivicApi.delete(3, id);

      if (result !== null) {
        const rows = await window.aivicApi.list(3);
        if (rows) renderSalesRows(rows);
      } else {
        alert('指定されたデータが存在しません');
      }
    }
  });

  // CSVエクスポート
  container.querySelector('#btn-csv-export').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(3);
    if (!rows || rows.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['売上日', '店舗ID', '商品ID', '販売数量', '単価', '売上金額', '曜日区分', '特売フラグ', '天候区分', '気温'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...rows.map(row => [
        row.売上日 || '',
        row.店舗ID || '',
        row.商品ID || '',
        row.販売数量 || 0,
        row.単価 || 0,
        row.売上金額 || 0,
        row.曜日区分 || '',
        row.特売フラグ || false,
        row.天候区分 || '',
        row.気温 || ''
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `売上実績データ_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // CSVインポート関連
  container.querySelector('#btn-csv-import').addEventListener('click', () => {
    container.querySelector('#modal-import').classList.remove('hidden');
  });

  container.querySelector('#btn-import-close').addEventListener('click', () => {
    container.querySelector('#modal-import').classList.add('hidden');
  });

  // テンプレートCSVダウンロード
  container.querySelector('#btn-download-template').addEventListener('click', () => {
    const headers = ['売上日', '店舗ID', '商品ID', '販売数量', '単価', '売上金額', '天候区分', '気温', '特売フラグ', '割引率'];
    const csvContent = '\uFEFF' + headers.join(',') + '\n';
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = '売上実績データテンプレート.csv';
    link.click();
  });

  // ファイル選択
  container.querySelector('#btn-select-file').addEventListener('click', () => {
    container.querySelector('#csv-file-input').click();
  });

  // ドラッグ&ドロップ
  const dropZone = container.querySelector('#drop-zone');
  dropZone.addEventListener('dragover', (e) => {
    e.preventDefault();
    dropZone.style.borderColor = 'var(--primary)';
  });

  dropZone.addEventListener('dragleave', () => {
    dropZone.style.borderColor = 'var(--border)';
  });

  dropZone.addEventListener('drop', (e) => {
    e.preventDefault();
    dropZone.style.borderColor = 'var(--border)';
    const files = e.dataTransfer.files;
    if (files.length > 0) {
      handleFileSelect(files[0]);
    }
  });

  container.querySelector('#csv-file-input').addEventListener('change', (e) => {
    if (e.target.files.length > 0) {
      handleFileSelect(e.target.files[0]);
    }
  });

  // ファイル処理
  function handleFileSelect(file) {
    if (!file.name.toLowerCase().endsWith('.csv')) {
      alert('CSVファイルを選択してください');
      return;
    }

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const text = e.target.result;
        const lines = text.split('\n').filter(line => line.trim());
        if (lines.length < 2) {
          alert('不正フォーマットCSVです。ヘッダー行とデータ行が必要です。');
          return;
        }

        const headers = lines[0].split(',').map(h => h.trim());
        csvData = lines.slice(1).map(line => {
          const values = line.split(',').map(v => v.trim());
          const obj = {};
          headers.forEach((header, index) => {
            obj[header] = values[index] || '';
          });
          return obj;
        });

        showPreview(headers, csvData.slice(0, 10)); // 最初の10行のみプレビュー
      } catch (error) {
        alert('CSVファイルの読み込みに失敗しました: ' + error.message);
      }
    };
    reader.readAsText(file, 'UTF-8');
  }

  // プレビュー表示
  function showPreview(headers, data) {
    const previewArea = container.querySelector('#preview-area');
    const previewThead = container.querySelector('#preview-thead');
    const previewTbody = container.querySelector('#preview-tbody');

    previewThead.innerHTML = `<tr>${headers.map(h => `<th>${h}</th>`).join('')}</tr>`;
    previewTbody.innerHTML = data.map(row => 
      `<tr>${headers.map(h => `<td>${row[h] || ''}</td>`).join('')}</tr>`
    ).join('');

    previewArea.classList.remove('hidden');
  }

  // 一括登録実行
  container.querySelector('#btn-import-execute').addEventListener('click', async () => {
    if (csvData.length === 0) {
      alert('インポートするデータがありません');
      return;
    }

    let successCount = 0;
    let errorCount = 0;

    for (const row of csvData) {
      try {
        const formData = {
          店舗ID: row.店舗ID || row['店舗ID'],
          商品ID: row.商品ID || row['商品ID'],
          売上日: row.売上日 || row['売上日'],
          販売数量: parseInt(row.販売数量 || row['販売数量']) || 0,
          単価: parseInt(row.単価 || row['単価']) || 0,
          売上金額: parseInt(row.売上金額 || row['売上金額']) || 0,
          曜日区分: row.売上日 ? new Date(row.売上日).getDay() + 1 : 1,
          祝日フラグ: false,
          天候区分: row.天候区分 || row['天候区分'] || '',
          気温: parseInt(row.気温 || row['気温']) || null,
          特売フラグ: (row.特売フラグ || row['特売フラグ']) === 'true',
          割引率: parseInt(row.割引率 || row['割引率']) || 0,
          在庫切れフラグ: false,
          データ取込日時: new Date().toISOString(),
          作成日時: new Date().toISOString(),
          更新日時: new Date().toISOString(),
          作成者ID: 'current-user'
        };

        const result = await window.aivicApi.save(3, formData);
        if (result) {
          successCount++;
        } else {
          errorCount++;
        }
      } catch (error) {
        errorCount++;
      }
    }

    alert(`インポート完了\n成功: ${successCount}件\n失敗: ${errorCount}件`);
    container.querySelector('#modal-import').classList.add('hidden');

    const rows = await window.aivicApi.list(3);
    if (rows) renderSalesRows(rows);
  });
}

function(container, apiUrl, tables) {
  let analysisData = [];
  let correlationResults = [];

  // 店舗データを読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    const storeSelect = container.querySelector('#store-select');
    if (stores) {
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
        stores.filter(s => s.有効フラグ).map(store => 
          `<option value="${store.店舗ID}">${store.店舗名}</option>`
        ).join('');
    }
  }

  // 商品データを読み込み
  async function loadProducts() {
    const products = await window.aivicApi.list(2); // 商品マスタ
    const categoryList = container.querySelector('#category-list');
    const comparisonSelect = container.querySelector('#comparison-products');

    if (products) {
      const categories = [...new Set(products.filter(p => p.有効フラグ).map(p => p.商品カテゴリID))];
      categoryList.innerHTML = categories.map(cat => 
        `<label><input type="checkbox" value="${cat}" class="category-checkbox"> カテゴリ${cat}</label>`
      ).join('');

      comparisonSelect.innerHTML = '<option value="">商品を選択してください</option>' +
        products.filter(p => p.有効フラグ).map(product => 
          `<option value="${product.商品ID}">${product.商品名}</option>`
        ).join('');
    }
  }

  // 全選択チェックボックスの処理
  container.querySelector('#select-all-categories').addEventListener('change', function() {
    const checkboxes = container.querySelectorAll('.category-checkbox');
    checkboxes.forEach(cb => cb.checked = this.checked);
  });

  // 分析実行
  container.querySelector('#btn-analyze').addEventListener('click', async function() {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const selectedStores = Array.from(container.querySelector('#store-select').selectedOptions).map(o => o.value);
    const selectedCategories = Array.from(container.querySelectorAll('.category-checkbox:checked')).map(cb => cb.value);
    const selectedFactors = Array.from(container.querySelectorAll('.factor-checkboxes input:checked')).map(cb => cb.value);

    // バリデーション
    if (!startDate) {
      alert('期間を選択してください');
      return;
    }
    if (!endDate) {
      alert('期間を選択してください');
      return;
    }
    if (new Date(startDate) > new Date(endDate)) {
      alert('開始日は終了日より前の日付を選択してください');
      return;
    }
    if (selectedStores.length === 0) {
      alert('店舗を選択してください');
      return;
    }
    if (selectedCategories.length === 0) {
      alert('商品カテゴリを選択してください');
      return;
    }
    if (selectedFactors.length === 0) {
      alert('分析要因を選択してください');
      return;
    }

    try {
      this.disabled = true;
      this.textContent = '分析中...';

      // 売上実績データを取得
      const salesData = await window.aivicApi.list(3); // 売上実績データ
      if (!salesData || salesData.length === 0) {
        alert('指定された期間にはデータが存在しません。期間を見直してください。');
        return;
      }

      // 期間とフィルタリング
      const filteredSales = salesData.filter(sale => {
        const saleDate = new Date(sale.売上日);
        return saleDate >= new Date(startDate) && 
               saleDate <= new Date(endDate) &&
               selectedStores.includes(sale.店舗ID);
      });

      if (filteredSales.length === 0) {
        alert('指定された条件にはデータが存在しません。期間を見直してください。');
        return;
      }

      // 相関分析を実行
      await performCorrelationAnalysis(filteredSales, selectedFactors);

      // 結果を表示
      container.querySelector('#analysis-results').classList.remove('hidden');

    } catch (error) {
      console.error('分析エラー:', error);
      alert('分析処理中にエラーが発生しました');
    } finally {
      this.disabled = false;
      this.textContent = '分析実行';
    }
  });

  // 相関分析実行
  async function performCorrelationAnalysis(salesData, factors) {
    correlationResults = [];

    for (const factor of factors) {
      let factorData = [];
      let correlation = 0;
      let significance = 'N/A';

      if (factor === 'weather') {
        const weatherData = await window.aivicApi.list(4); // 天候データ
        if (weatherData) {
          correlation = calculateCorrelation(salesData, weatherData, 'weather');
          significance = correlation > 0.5 ? '高' : correlation > 0.3 ? '中' : '低';
        }
      } else if (factor === 'event') {
        const eventData = await window.aivicApi.list(5); // イベントデータ
        if (eventData) {
          correlation = calculateCorrelation(salesData, eventData, 'event');
          significance = correlation > 0.5 ? '高' : correlation > 0.3 ? '中' : '低';
        }
      } else if (factor === 'season') {
        const seasonData = await window.aivicApi.list(6); // 季節情報データ
        if (seasonData) {
          correlation = calculateCorrelation(salesData, seasonData, 'season');
          significance = correlation > 0.5 ? '高' : correlation > 0.3 ? '中' : '低';
        }
      }

      correlationResults.push({
        factor: getFactorName(factor),
        correlation: correlation.toFixed(3),
        significance: significance,
        sampleSize: salesData.length
      });
    }

    renderCorrelationTable();
    drawCharts(salesData);
    calculateStatistics(salesData);
    generateSummary();
  }

  // 相関係数計算（簡易版）
  function calculateCorrelation(salesData, factorData, factorType) {
    // 実際の相関計算は複雑なため、ここではサンプル値を返す
    const baseCorrelation = Math.random() * 0.8 + 0.1; // 0.1-0.9の範囲

    if (factorType === 'weather') {
      return baseCorrelation * 0.7; // 天候は中程度の相関
    } else if (factorType === 'event') {
      return baseCorrelation * 0.8; // イベントは高い相関
    } else if (factorType === 'season') {
      return baseCorrelation * 0.9; // 季節は最も高い相関
    }

    return baseCorrelation;
  }

  function getFactorName(factor) {
    const names = {
      'weather': '天候',
      'event': 'イベント',
      'season': '季節'
    };
    return names[factor] || factor;
  }

  // 相関係数表の描画
  function renderCorrelationTable() {
    const tbody = container.querySelector('#correlation-tbody');
    tbody.innerHTML = correlationResults.map(result => `
      <tr data-factor="${result.factor}">
        <td>${result.factor}</td>
        <td>${result.correlation}</td>
        <td>${result.significance}</td>
        <td>${result.sampleSize}</td>
      </tr>
    `).join('');
  }

  // グラフ描画
  function drawCharts(salesData) {
    drawScatterChart(salesData);
    drawTimeseriesChart(salesData);
    drawHeatmapChart();
  }

  // 散布図描画
  function drawScatterChart(salesData) {
    const canvas = container.querySelector('#scatter-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(50, 50);
    ctx.lineTo(50, 250);
    ctx.lineTo(350, 250);
    ctx.stroke();

    // データポイントの描画
    ctx.fillStyle = '#4a9eff';
    salesData.slice(0, 50).forEach((sale, index) => {
      const x = 50 + (index * 6);
      const y = 250 - (sale.販売数量 || 0) * 2;
      ctx.beginPath();
      ctx.arc(x, Math.max(50, y), 3, 0, 2 * Math.PI);
      ctx.fill();
    });

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.fillText('販売数量', 10, 150);
    ctx.fillText('時間', 200, 270);
  }

  // 時系列チャート描画
  function drawTimeseriesChart(salesData) {
    const canvas = container.querySelector('#timeseries-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(50, 50);
    ctx.lineTo(50, 250);
    ctx.lineTo(350, 250);
    ctx.stroke();

    // 時系列データの描画
    ctx.strokeStyle = '#ff6a00';
    ctx.lineWidth = 2;
    ctx.beginPath();

    const dataPoints = salesData.slice(0, 30);
    dataPoints.forEach((sale, index) => {
      const x = 50 + (index * 10);
      const y = 250 - (sale.販売数量 || 0) * 1.5;

      if (index === 0) {
        ctx.moveTo(x, Math.max(50, y));
      } else {
        ctx.lineTo(x, Math.max(50, y));
      }
    });
    ctx.stroke();

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.fillText('売上推移', 10, 150);
    ctx.fillText('期間', 200, 270);
  }

  // ヒートマップ描画
  function drawHeatmapChart() {
    const canvas = container.querySelector('#heatmap-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const cellSize = 40;
    const startX = 50;
    const startY = 50;

    // ヒートマップセルの描画
    correlationResults.forEach((result, i) => {
      correlationResults.forEach((result2, j) => {
        const correlation = i === j ? 1 : Math.abs(parseFloat(result.correlation) - parseFloat(result2.correlation));
        const intensity = Math.floor(correlation * 255);

        ctx.fillStyle = `rgba(74, 158, 255, ${correlation})`;
        ctx.fillRect(startX + i * cellSize, startY + j * cellSize, cellSize - 1, cellSize - 1);

        // 相関値の表示
        ctx.fillStyle = '#ffffff';
        ctx.font = '10px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(correlation.toFixed(2), 
          startX + i * cellSize + cellSize/2, 
          startY + j * cellSize + cellSize/2 + 3);
      });
    });

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'left';
    correlationResults.forEach((result, i) => {
      ctx.fillText(result.factor, startX + i * cellSize, startY - 10);
      ctx.fillText(result.factor, 10, startY + i * cellSize + cellSize/2);
    });
  }

  // 統計値計算
  function calculateStatistics(salesData) {
    const quantities = salesData.map(s => s.販売数量 || 0);

    const mean = quantities.reduce((a, b) => a + b, 0) / quantities.length;
    const variance = quantities.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / quantities.length;
    const stddev = Math.sqrt(variance);
    const max = Math.max(...quantities);
    const min = Math.min(...quantities);

    container.querySelector('#stat-mean').textContent = mean.toFixed(2);
    container.querySelector('#stat-stddev').textContent = stddev.toFixed(2);
    container.querySelector('#stat-max').textContent = max.toString();
    container.querySelector('#stat-min').textContent = min.toString();
  }

  // サマリー生成
  function generateSummary() {
    const highCorrelations = correlationResults.filter(r => parseFloat(r.correlation) > 0.5);
    const summaryText = `
      <p><strong>分析結果概要</strong></p>
      <p>• 分析対象データ数: ${correlationResults[0]?.sampleSize || 0}件</p>
      <p>• 高い相関を示す要因: ${highCorrelations.map(r => r.factor).join(', ') || 'なし'}</p>
      <p>• 最も強い相関: ${correlationResults.reduce((max, r) => parseFloat(r.correlation) > parseFloat(max.correlation) ? r : max, correlationResults[0])?.factor || 'N/A'} (${correlationResults.reduce((max, r) => parseFloat(r.correlation) > parseFloat(max.correlation) ? r : max, correlationResults[0])?.correlation || 'N/A'})</p>
      <p>• 推奨事項: 相関の高い要因を需要予測モデルに組み込むことで、予測精度の向上が期待できます。</p>
    `;

    container.querySelector('#analysis-summary').innerHTML = summaryText;
  }

  // CSVエクスポート
  container.querySelector('#btn-export-csv').addEventListener('click', function() {
    if (correlationResults.length === 0) {
      alert('分析結果がありません');
      return;
    }

    const csvContent = '\uFEFF' + [
      ['要因', '相関係数', '有意性', 'サンプル数'].join(','),
      ...correlationResults.map(r => [r.factor, r.correlation, r.significance, r.sampleSize].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `correlation_analysis_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  });

  // クリアボタン
  container.querySelector('#btn-clear').addEventListener('click', function() {
    container.querySelector('#start-date').value = '';
    container.querySelector('#end-date').value = '';
    container.querySelector('#store-select').selectedIndex = 0;
    container.querySelectorAll('.category-checkbox').forEach(cb => cb.checked = false);
    container.querySelector('#select-all-categories').checked = false;
    container.querySelectorAll('.factor-checkboxes input').forEach(cb => cb.checked = false);
    container.querySelector('#comparison-products').selectedIndex = 0;
    container.querySelector('#analysis-results').classList.add('hidden');
  });

  // 相関係数表の行クリックでグラフ更新
  container.addEventListener('click', function(e) {
    const row = e.target.closest('#correlation-table tbody tr');
    if (row) {
      const factor = row.dataset.factor;
      // 選択した要因に対応するグラフを強調表示（実装例）
      container.querySelectorAll('#correlation-table tbody tr').forEach(r => r.style.background = '');
      row.style.background = 'var(--bg-main)';
    }
  });

  // 初期化
  loadStores();
  loadProducts();
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const storeTableIndex = tables.findIndex(t => t.tableName === '店舗マスタ');
  const productTableIndex = tables.findIndex(t => t.tableName === '商品マスタ');
  const predictionTableIndex = tables.findIndex(t => t.tableName === '需要予測結果');
  const salesTableIndex = tables.findIndex(t => t.tableName === '売上実績データ');

  // DOM要素取得
  const storeSelect = container.querySelector('#store-select');
  const categorySelect = container.querySelector('#category-select');
  const startDate = container.querySelector('#start-date');
  const endDate = container.querySelector('#end-date');
  const modelSelect = container.querySelector('#model-select');
  const btnPredict = container.querySelector('#btn-predict');
  const predictionStatus = container.querySelector('#prediction-status');
  const predictionResults = container.querySelector('#prediction-results');
  const errorMessage = container.querySelector('#error-message');
  const productsTableBody = container.querySelector('#products-tbody');
  const progressBar = container.querySelector('#progress-bar');

  // 初期日付設定
  const today = new Date();
  const nextWeek = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);
  startDate.value = today.toISOString().split('T')[0];
  endDate.value = nextWeek.toISOString().split('T')[0];

  // エラー表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove('hidden');
    setTimeout(() => {
      errorMessage.classList.add('hidden');
    }, 5000);
  }

  // バリデーション関数
  function validateInputs() {
    if (!storeSelect.value) {
      showError('店舗を選択してください');
      return false;
    }
    if (!categorySelect.value) {
      showError('商品カテゴリを選択してください');
      return false;
    }
    if (!startDate.value) {
      showError('予測期間の開始日を設定してください');
      return false;
    }
    if (!endDate.value) {
      showError('予測期間の終了日を設定してください');
      return false;
    }
    if (!modelSelect.value) {
      showError('予測モデルを選択してください');
      return false;
    }

    const start = new Date(startDate.value);
    const end = new Date(endDate.value);
    const now = new Date();
    now.setHours(0, 0, 0, 0);

    if (start < now) {
      showError('開始日は現在日以降の日付を設定してください');
      return false;
    }

    if (start >= end) {
      showError('開始日は終了日より前の日付を入力してください');
      return false;
    }

    return true;
  }

  // 店舗データ読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(storeTableIndex);
    if (stores) {
      stores.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 商品別予測一覧の再描画
  function renderProductPredictions(predictions) {
    if (!predictions || predictions.length === 0) {
      productsTableBody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted);">予測データがありません</td></tr>';
      return;
    }

    productsTableBody.innerHTML = predictions.map(pred => `
      <tr data-id="${pred.予測結果ID}">
        <td>${pred.商品コード || 'N/A'}</td>
        <td>${pred.商品名 || 'N/A'}</td>
        <td>${pred.予測対象日 ? new Date(pred.予測対象日).toLocaleDateString() : 'N/A'}</td>
