      const quantity = parseInt(quantityInput.value);
      if (quantity <= 0) {
        alert('発注量は正の数値を入力してください');
        return;
      }

      // モーダル表示
      selectedProductId = productId;
      container.querySelector('#modal-product-name').textContent = product.商品名;
      container.querySelector('#modal-order-quantity').value = quantity;
      container.querySelector('#modal-order-reason').value = reasonInput.value;

      // 納期予定日を7日後に設定
      const deliveryDate = new Date();
      deliveryDate.setDate(deliveryDate.getDate() + 7);
      container.querySelector('#modal-delivery-date').value = deliveryDate.toISOString().split('T')[0];

      container.querySelector('#order-modal').classList.remove('hidden');
    }
  });

  // 数量入力バリデーション
  container.addEventListener('input', (e) => {
    if (e.target.classList.contains('quantity-input')) {
      const value = e.target.value;
      if (value && (isNaN(value) || parseFloat(value) < 0)) {
        e.target.setCustomValidity('発注量は正の数値を入力してください');
      } else {
        e.target.setCustomValidity('');
      }
    }
  });

  // モーダル関連
  container.querySelector('#modal-close').addEventListener('click', () => {
    container.querySelector('#order-modal').classList.add('hidden');
  });

  container.querySelector('#btn-order-cancel').addEventListener('click', () => {
    container.querySelector('#order-modal').classList.add('hidden');
  });

  container.querySelector('#btn-order-execute').addEventListener('click', () => {
    const quantity = container.querySelector('#modal-order-quantity').value;
    const reason = container.querySelector('#modal-order-reason').value;

    if (!quantity || quantity <= 0) {
      alert('発注量は正の数値を入力してください');
      return;
    }

    executeOrder(selectedProductId, quantity, reason);
  });

  // モーダル外クリックで閉じる
  container.querySelector('#order-modal').addEventListener('click', (e) => {
    if (e.target.id === 'order-modal') {
      container.querySelector('#order-modal').classList.add('hidden');
    }
  });
}

function(container, apiUrl, tables) {
  const logTableIndex = 12; // データ収集ログテーブルのインデックス
  const storeTableIndex = 1; // 店舗マスタテーブルのインデックス

  let allLogs = [];
  let stores = [];
  let autoRefreshInterval = null;

  // 店舗マスタを取得
  async function loadStores() {
    const storeData = await window.aivicApi.list(storeTableIndex);
    if (storeData) {
      stores = storeData;
    }
  }

  // 店舗名を取得する関数
  function getStoreName(storeId) {
    const store = stores.find(s => s.店舗ID === storeId);
    return store ? store.店舗名 : '不明';
  }

  // ステータス表示用の関数
  function getStatusBadge(status) {
    const statusColors = {
      '成功': '#28a745',
      '失敗': '#dc3545',
      '警告': '#ffc107',
      '実行中': '#17a2b8'
    };
    const color = statusColors[status] || '#6c757d';
    return `<span style="padding: 4px 8px; border-radius: 4px; background: ${color}; color: white; font-size: 12px;">${status}</span>`;
  }

  // 日時フォーマット関数
  function formatDateTime(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP');
  }

  // サマリー更新関数
  function updateSummary(logs) {
    const successCount = logs.filter(log => log.処理ステータス === '成功').length;
    const errorCount = logs.filter(log => log.処理ステータス === '失敗').length;
    const warningCount = logs.filter(log => log.処理ステータス === '警告').length;

    const lastUpdate = logs.length > 0 ? 
      Math.max(...logs.map(log => new Date(log.収集開始日時 || 0).getTime())) : 0;

    container.querySelector('#summary-success').textContent = successCount;
    container.querySelector('#summary-error').textContent = errorCount;
    container.querySelector('#summary-warning').textContent = warningCount;
    container.querySelector('#summary-last-update').textContent = 
      lastUpdate > 0 ? formatDateTime(new Date(lastUpdate)) : '-';

    // システム状況インジケーター更新
    const statusIndicator = container.querySelector('#status-indicator');
    const recentErrors = logs.filter(log => {
      const logTime = new Date(log.収集開始日時);
      const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000);
      return log.処理ステータス === '失敗' && logTime > oneHourAgo;
    }).length;

    if (recentErrors > 0) {
      statusIndicator.innerHTML = `
        <div style="width: 12px; height: 12px; border-radius: 50%; background: #dc3545;"></div>
        <span style="color: var(--text);">エラー発生中 (${recentErrors}件)</span>
      `;
    } else {
      statusIndicator.innerHTML = `
        <div style="width: 12px; height: 12px; border-radius: 50%; background: #28a745;"></div>
        <span style="color: var(--text);">正常稼働中</span>
      `;
    }
  }

  // ログ一覧再描画関数
  function renderLogs(logs) {
    const tbody = container.querySelector('#log-table-body');

    tbody.innerHTML = logs.map(log => `
      <tr data-id="${log.ログID}">
        <td>${formatDateTime(log.収集開始日時)}</td>
        <td>${log.データソース || '-'}</td>
        <td>${log.データ種別 || '-'}</td>
        <td>${getStoreName(log.店舗ID)}</td>
        <td>${getStatusBadge(log.処理ステータス)}</td>
        <td>${log.収集件数 || 0}</td>
        <td>${log.エラー件数 || 0}</td>
        <td>${log.処理時間秒 ? log.処理時間秒 + '秒' : '-'}</td>
        <td>${log.データ品質スコア || '-'}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${log.ログID}">詳細</button>
          ${log.処理ステータス === '失敗' ? 
            `<button class="action-btn secondary retry-btn" data-id="${log.ログID}">再実行</button>` : ''}
        </td>
      </tr>
    `).join('');

    container.querySelector('#log-count').textContent = `${logs.length}件`;
    updateSummary(logs);
  }

  // フィルタリング関数
  function applyFilters() {
    const dataSource = container.querySelector('#filter-data-source').value;
    const logLevel = container.querySelector('#filter-log-level').value;
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;

    // 日付範囲の妥当性チェック
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('開始日は終了日より前の日付を設定してください');
      return;
    }

    let filteredLogs = allLogs.filter(log => {
      // データソースフィルター
      if (dataSource && log.データソース !== dataSource) return false;

      // ログレベルフィルター
      if (logLevel && log.処理ステータス !== logLevel) return false;

      // 日付範囲フィルター
      if (startDate) {
        const logDate = new Date(log.収集開始日時);
        if (logDate < new Date(startDate)) return false;
      }
      if (endDate) {
        const logDate = new Date(log.収集開始日時);
        if (logDate > new Date(endDate)) return false;
      }

      return true;
    });

    renderLogs(filteredLogs);
  }

  // ログ詳細表示関数
  function showLogDetail(logId) {
    const log = allLogs.find(l => l.ログID === logId);
    if (!log) return;

    const content = container.querySelector('#log-detail-content');
    content.innerHTML = `
      <div style="display: grid; gap: 15px;">
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 15px;">
          <div>
            <label style="font-weight: bold; color: var(--text);">ログID</label>
            <div style="color: var(--text-muted);">${log.ログID}</div>
          </div>
          <div>
            <label style="font-weight: bold; color: var(--text);">データ種別</label>
            <div style="color: var(--text-muted);">${log.データ種別 || '-'}</div>
          </div>
          <div>
            <label style="font-weight: bold; color: var(--text);">データソース</label>
            <div style="color: var(--text-muted);">${log.データソース || '-'}</div>
          </div>
          <div>
            <label style="font-weight: bold; color: var(--text);">店舗</label>
            <div style="color: var(--text-muted);">${getStoreName(log.店舗ID)}</div>
          </div>
          <div>
            <label style="font-weight: bold; color: var(--text);">収集開始日時</label>
            <div style="color: var(--text-muted);">${formatDateTime(log.収集開始日時)}</div>
          </div>
          <div>
            <label style="font-weight: bold; color: var(--text);">収集終了日時</label>
            <div style="color: var(--text-muted);">${formatDateTime(log.収集終了日時)}</div>
          </div>
          <div>
            <label style="font-weight: bold; color: var(--text);">処理ステータス</label>
            <div>${getStatusBadge(log.処理ステータス)}</div>
          </div>
          <div>
            <label style="font-weight: bold; color: var(--text);">処理時間</label>
            <div style="color: var(--text-muted);">${log.処理時間秒 ? log.処理時間秒 + '秒' : '-'}</div>
          </div>
          <div>
            <label style="font-weight: bold; color: var(--text);">収集件数</label>
            <div style="color: var(--text-muted);">${log.収集件数 || 0}</div>
          </div>
          <div>
            <label style="font-weight: bold; color: var(--text);">エラー件数</label>
            <div style="color: var(--text-muted);">${log.エラー件数 || 0}</div>
          </div>
          <div>
            <label style="font-weight: bold; color: var(--text);">データ品質スコア</label>
            <div style="color: var(--text-muted);">${log.データ品質スコア || '-'}</div>
          </div>
          <div>
            <label style="font-weight: bold; color: var(--text);">対象期間</label>
            <div style="color: var(--text-muted);">${formatDateTime(log.対象期間開始日)} ～ ${formatDateTime(log.対象期間終了日)}</div>
          </div>
        </div>
        ${log.エラーメッセージ ? `
          <div>
            <label style="font-weight: bold; color: var(--text);">エラーメッセージ</label>
            <div style="background: var(--bg-main); padding: 10px; border-radius: 4px; border-left: 3px solid #dc3545; color: var(--text); white-space: pre-wrap; max-height: 200px; overflow-y: auto;">${log.エラーメッセージ}</div>
          </div>
        ` : ''}
        ${log.備考 ? `
          <div>
            <label style="font-weight: bold; color: var(--text);">備考</label>
            <div style="background: var(--bg-main); padding: 10px; border-radius: 4px; color: var(--text); white-space: pre-wrap;">${log.備考}</div>
          </div>
        ` : ''}
      </div>
    `;

    container.querySelector('#log-detail-modal').classList.remove('hidden');
  }

  // CSVエクスポート関数
  function exportCSV() {
    const dataSource = container.querySelector('#filter-data-source').value;
    const logLevel = container.querySelector('#filter-log-level').value;
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;

    let exportLogs = allLogs;

    // フィルター適用
    if (dataSource || logLevel || startDate || endDate) {
      exportLogs = allLogs.filter(log => {
        if (dataSource && log.データソース !== dataSource) return false;
        if (logLevel && log.処理ステータス !== logLevel) return false;
        if (startDate && new Date(log.収集開始日時) < new Date(startDate)) return false;
        if (endDate && new Date(log.収集開始日時) > new Date(endDate)) return false;
        return true;
      });
    }

    const headers = ['ログID', '収集開始日時', '収集終了日時', 'データ種別', 'データソース', '店舗名', '処理ステータス', '収集件数', 'エラー件数', '処理時間秒', 'データ品質スコア', 'エラーメッセージ', '備考'];

    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...exportLogs.map(log => [
        log.ログID,
        log.収集開始日時,
        log.収集終了日時,
        log.データ種別,
        log.データソース,
        getStoreName(log.店舗ID),
        log.処理ステータス,
        log.収集件数 || 0,
        log.エラー件数 || 0,
        log.処理時間秒 || '',
        log.データ品質スコア || '',
        `"${(log.エラーメッセージ || '').replace(/"/g, '""')}"`,
        `"${(log.備考 || '').replace(/"/g, '""')}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `data_collection_logs_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // エラーログ再実行関数
  async function retryLog(logId) {
    if (!confirm('このログの処理を再実行しますか？')) return;

    try {
      // 再実行フラグを更新
      const updated = await window.aivicApi.update(logTableIndex, logId, {
        再実行フラグ: true,
        処理ステータス: '実行中',
        更新日時: new Date().toISOString()
      });

      if (updated) {
        alert('再実行を開始しました');
        loadLogs();
      } else {
        alert('エラーログの再実行が失敗しました');
      }
    } catch (error) {
      alert('エラーログの再実行が失敗しました');
    }
  }

  // 自動更新機能
  function toggleAutoRefresh() {
    const toggle = container.querySelector('#auto-refresh-toggle');

    if (toggle.checked) {
      autoRefreshInterval = setInterval(() => {
        loadLogs();
      }, 30000); // 30秒間隔
    } else {
      if (autoRefreshInterval) {
        clearInterval(autoRefreshInterval);
        autoRefreshInterval = null;
      }
    }
  }

  // ログデータ読み込み関数
  async function loadLogs() {
    const logs = await window.aivicApi.list(logTableIndex);
    if (logs) {
      allLogs = logs.sort((a, b) => new Date(b.収集開始日時) - new Date(a.収集開始日時));
      renderLogs(allLogs);
    }
  }

  // 初期データ読み込み
  loadStores().then(() => {
    allLogs = (tables[logTableIndex]?.records || []).sort((a, b) => new Date(b.収集開始日時) - new Date(a.収集開始日時));
    renderLogs(allLogs);
    loadLogs();
  });

  // イベントリスナー設定

  // 検索・絞り込みボタン
  container.querySelector('#btn-search').addEventListener('click', applyFilters);

  // 条件クリアボタン
  container.querySelector('#btn-clear-filters').addEventListener('click', () => {
    container.querySelector('#filter-data-source').value = '';
    container.querySelector('#filter-log-level').value = '';
    container.querySelector('#filter-start-date').value = '';
    container.querySelector('#filter-end-date').value = '';
    renderLogs(allLogs);
  });

  // CSVエクスポートボタン
  container.querySelector('#btn-export-csv').addEventListener('click', exportCSV);

  // 自動更新トグル
  container.querySelector('#auto-refresh-toggle').addEventListener('change', toggleAutoRefresh);

  // アラート設定ボタン
  container.querySelector('#btn-alert-settings').addEventListener('click', () => {
    container.querySelector('#alert-settings-modal').classList.remove('hidden');
  });

  // モーダル閉じるボタン
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#log-detail-modal').classList.add('hidden');
  });

  container.querySelector('#btn-close-alert-modal').addEventListener('click', () => {
    container.querySelector('#alert-settings-modal').classList.add('hidden');
  });

  // アラート設定保存
  container.querySelector('#btn-save-alert-settings').addEventListener('click', () => {
    alert('アラート通知設定を保存しました');
    container.querySelector('#alert-settings-modal').classList.add('hidden');
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 詳細ボタン
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      showLogDetail(detailBtn.dataset.id);
      return;
    }

    // 再実行ボタン
    const retryBtn = e.target.closest('.retry-btn');
    if (retryBtn) {
      await retryLog(retryBtn.dataset.id);
      return;
    }
  });

  // モーダル背景クリックで閉じる
  container.querySelector('#log-detail-modal').addEventListener('click', (e) => {
    if (e.target.id === 'log-detail-modal') {
      container.querySelector('#log-detail-modal').classList.add('hidden');
    }
  });

  container.querySelector('#alert-settings-modal').addEventListener('click', (e) => {
    if (e.target.id === 'alert-settings-modal') {
      container.querySelector('#alert-settings-modal').classList.add('hidden');
    }
  });
}

function(container, apiUrl, tables) {
  let currentPage = 1;
  const itemsPerPage = 20;
  let allHistories = [];
  let filteredHistories = [];
  let users = [];

  // ユーザー一覧を取得してセレクトボックスに設定
  async function loadUsers() {
    try {
      const userRows = await window.aivicApi.list(0); // ログインユーザーテーブル
      if (userRows) {
        users = userRows;
        const userSelect = container.querySelector("#filter-user");
        userSelect.innerHTML = '<option value="">全ユーザー</option>';
        users.forEach(user => {
          userSelect.innerHTML += `<option value="${user.ユーザーID}">${user.ユーザー名}</option>`;
        });
      }
    } catch (error) {
      console.error('ユーザー一覧の取得に失敗:', error);
    }
  }

  // 日付フォーマット関数
  function formatDateTime(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
  }

  // ユーザー名取得関数
  function getUserName(userId) {
    const user = users.find(u => u.ユーザーID === userId);
    return user ? user.ユーザー名 : userId || '';
  }

  // 処理結果のバッジスタイル
  function getResultBadge(result) {
    const colors = {
      '成功': 'background: #28a745; color: white;',
      '失敗': 'background: #dc3545; color: white;',
      'エラー': 'background: #ffc107; color: #212529;'
    };
    const style = colors[result] || 'background: var(--bg-main); color: var(--text);';
    return `<span style="padding: 2px 8px; border-radius: 12px; font-size: 12px; ${style}">${result || ''}</span>`;
  }

  // テーブル再描画関数
  function renderRows(histories) {
    const tbody = container.querySelector("#history-tbody");
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageHistories = histories.slice(startIndex, endIndex);

    if (pageHistories.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted); padding: 32px;">該当する操作履歴が見つかりませんでした</td></tr>';
    } else {
      tbody.innerHTML = pageHistories.map(h => `
        <tr data-id="${h.操作履歴ID}">
          <td>${formatDateTime(h.操作日時)}</td>
          <td>${getUserName(h.ユーザーID)}</td>
          <td>${h.操作種別 || ''}</td>
          <td>${h.操作画面 || ''}</td>
          <td>${h.IPアドレス || ''}</td>
          <td>${getResultBadge(h.処理結果)}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${h.操作履歴ID}">詳細</button>
          </td>
        </tr>
      `).join("");
    }

    // 結果件数表示
    const resultCount = container.querySelector("#result-count");
    resultCount.textContent = `${histories.length}件の履歴が見つかりました`;

    // ページネーション更新
    updatePagination(histories.length);
  }

  // ページネーション更新
  function updatePagination(totalItems) {
    const totalPages = Math.ceil(totalItems / itemsPerPage);
    const pageInfo = container.querySelector("#page-info");
    const btnPrev = container.querySelector("#btn-prev");
    const btnNext = container.querySelector("#btn-next");

    pageInfo.textContent = `${currentPage} / ${totalPages} ページ (${totalItems}件)`;
    btnPrev.disabled = currentPage <= 1;
    btnNext.disabled = currentPage >= totalPages;

    if (totalPages <= 1) {
      container.querySelector("#pagination").style.display = 'none';
    } else {
      container.querySelector("#pagination").style.display = 'flex';
    }
  }

  // フィルター適用
  function applyFilters() {
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;
    const userId = container.querySelector("#filter-user").value;
    const operationType = container.querySelector("#filter-operation-type").value;
    const screenName = container.querySelector("#filter-screen-name").value.toLowerCase();
    const ipAddress = container.querySelector("#filter-ip-address").value.toLowerCase();
    const result = container.querySelector("#filter-result").value;

    // 日付範囲バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('開始日が終了日より後の日付になっています。正しい日付範囲を入力してください。');
      return;
    }

    // IPアドレス形式バリデーション
    if (ipAddress && ipAddress !== '') {
      const ipPattern = /^(\d{1,3}\.){3}\d{1,3}$/;
      if (!ipPattern.test(ipAddress)) {
        const parts = ipAddress.split('.');
        if (parts.length === 4) {
          const invalidPart = parts.find(part => parseInt(part) > 255 || parseInt(part) < 0 || isNaN(parseInt(part)));
          if (invalidPart !== undefined) {
            alert('不正なIPアドレス形式です。正しい形式で入力してください（例：192.168.1.100）');
            return;
          }
        } else {
          alert('不正なIPアドレス形式です。正しい形式で入力してください（例：192.168.1.100）');
          return;
        }
      }
    }

    filteredHistories = allHistories.filter(h => {
      // 日付範囲フィルター
      if (startDate && h.操作日時) {
        const historyDate = new Date(h.操作日時).toISOString().split('T')[0];
        if (historyDate < startDate) return false;
      }
      if (endDate && h.操作日時) {
        const historyDate = new Date(h.操作日時).toISOString().split('T')[0];
        if (historyDate > endDate) return false;
      }

      // ユーザーフィルター
      if (userId && h.ユーザーID !== userId) return false;

      // 操作種別フィルター
      if (operationType && h.操作種別 !== operationType) return false;

      // 画面名フィルター
      if (screenName && (!h.操作画面 || !h.操作画面.toLowerCase().includes(screenName))) return false;

      // IPアドレスフィルター
      if (ipAddress && (!h.IPアドレス || !h.IPアドレス.toLowerCase().includes(ipAddress))) return false;

      // 処理結果フィルター
      if (result && h.処理結果 !== result) return false;

      return true;
    });

    currentPage = 1;
    renderRows(filteredHistories);
  }

  // 検索条件クリア
  function clearFilters() {
    container.querySelector("#filter-start-date").value = '';
    container.querySelector("#filter-end-date").value = '';
    container.querySelector("#filter-user").value = '';
    container.querySelector("#filter-operation-type").value = '';
    container.querySelector("#filter-screen-name").value = '';
    container.querySelector("#filter-ip-address").value = '';
    container.querySelector("#filter-result").value = '';

    filteredHistories = [...allHistories];
    currentPage = 1;
    renderRows(filteredHistories);
  }

  // CSV出力
  function exportCSV() {
    if (filteredHistories.length === 0) {
      alert('出力するデータがありません。');
      return;
    }

    // 大量データの場合の警告
    if (filteredHistories.length > 100000) {
      alert('データ量が多すぎるため、CSV出力でタイムアウトエラーが発生する可能性があります。検索条件を絞り込んでから再度お試しください。');
      return;
    }

    try {
      const headers = ['操作日時', 'ユーザー名', '操作種別', '操作画面', '操作対象テーブル', '操作対象ID', '操作内容', 'IPアドレス', 'ユーザーエージェント', '処理結果', 'エラーメッセージ', '処理時間'];
      const csvContent = [
        headers.join(','),
        ...filteredHistories.map(h => [
          `"${formatDateTime(h.操作日時)}"`,
          `"${getUserName(h.ユーザーID)}"`,
          `"${h.操作種別 || ''}"`,
          `"${h.操作画面 || ''}"`,
          `"${h.操作対象テーブル || ''}"`,
          `"${h.操作対象ID || ''}"`,
          `"${(h.操作内容 || '').replace(/"/g, '""')}"`,
          `"${h.IPアドレス || ''}"`,
          `"${(h.ユーザーエージェント || '').replace(/"/g, '""')}"`,
          `"${h.処理結果 || ''}"`,
          `"${(h.エラーメッセージ || '').replace(/"/g, '""')}"`,
          `"${h.処理時間 || ''}ms"`
        ].join(','))
      ].join('\n');

      const bom = '\uFEFF';
      const blob = new Blob([bom + csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `システム操作履歴_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      alert('CSV出力中にエラーが発生しました。データ量を減らして再度お試しください。');
    }
  }

  // 詳細モーダル表示
  function showDetailModal(historyId) {
    const history = allHistories.find(h => h.操作履歴ID === historyId);
    if (!history) return;

    container.querySelector("#detail-datetime").textContent = formatDateTime(history.操作日時);
    container.querySelector("#detail-user").textContent = getUserName(history.ユーザーID);
    container.querySelector("#detail-operation-type").textContent = history.操作種別 || '';
    container.querySelector("#detail-screen").textContent = history.操作画面 || '';
    container.querySelector("#detail-target-table").textContent = history.操作対象テーブル || '';
    container.querySelector("#detail-target-id").textContent = history.操作対象ID || '';
    container.querySelector("#detail-content-text").textContent = history.操作内容 || '';
    container.querySelector("#detail-ip").textContent = history.IPアドレス || '';
    container.querySelector("#detail-user-agent").textContent = history.ユーザーエージェント || '';
    container.querySelector("#detail-result").textContent = history.処理結果 || '';
    container.querySelector("#detail-error").textContent = history.エラーメッセージ || '';
    container.querySelector("#detail-processing-time").textContent = history.処理時間 ? `${history.処理時間}ms` : '';

    container.querySelector("#detail-modal").style.display = 'block';
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      const histories = await window.aivicApi.list(12); // システム操作履歴テーブル
      if (histories) {
        allHistories = histories.sort((a, b) => new Date(b.操作日時) - new Date(a.操作日時));
        filteredHistories = [...allHistories];
        renderRows(filteredHistories);
      }
    } catch (error) {
      console.error('操作履歴の取得に失敗:', error);
      const tbody = container.querySelector("#history-tbody");
      tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted); padding: 32px;">データの取得に失敗しました</td></tr>';
    }
  }

  // イベントリスナー設定
  container.querySelector("#btn-search").addEventListener("click", applyFilters);
  container.querySelector("#btn-clear").addEventListener("click", clearFilters);
  container.querySelector("#btn-csv-export").addEventListener("click", exportCSV);

  // ページネーション
  container.querySelector("#btn-prev").addEventListener("click", () => {
    if (currentPage > 1) {
      currentPage--;
      renderRows(filteredHistories);
    }
  });

  container.querySelector("#btn-next").addEventListener("click", () => {
    const totalPages = Math.ceil(filteredHistories.length / itemsPerPage);
    if (currentPage < totalPages) {
      currentPage++;
      renderRows(filteredHistories);
    }
  });

  // 詳細ボタンクリック
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
    }
  });

  // モーダル閉じる
  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#detail-modal").style.display = 'none';
  });

  // モーダル背景クリックで閉じる
  container.querySelector("#detail-modal").addEventListener("click", (e) => {
    if (e.target.id === 'detail-modal') {
      container.querySelector("#detail-modal").style.display = 'none';
    }
  });

  // 初期化
  loadUsers();
  loadData();
}

function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const STORES_TABLE = 1;
  const PRODUCTS_TABLE = 2;
  const PREDICTION_RESULTS_TABLE = 10;
  const WEATHER_DATA_TABLE = 4;
  const EVENT_DATA_TABLE = 5;

  // 予測結果再描画関数
  function renderPredictionResults(results) {
    const tbody = container.querySelector("#prediction-results-tbody");
    if (!results || results.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted); padding: 40px;">予測結果がありません</td></tr>';
      return;
    }

    tbody.innerHTML = results.map(r => `
      <tr data-id="${r.id}">
        <td>${r.store_name || ""}</td>
        <td>${r.product_name || ""}</td>
        <td>${r.prediction_date ? new Date(r.prediction_date).toLocaleDateString() : ""}</td>
        <td>${r.predicted_quantity || 0}</td>
        <td>${r.prediction_accuracy ? (r.prediction_accuracy + "%") : ""}</td>
        <td>${r.recommended_order_quantity || 0}</td>
        <td>
          <span style="padding: 2px 8px; border-radius: 4px; font-size: 12px; 
            ${r.prediction_status === '完了' ? 'background: rgba(34, 197, 94, 0.1); color: #22c55e; border: 1px solid #22c55e;' : 
              r.prediction_status === '算出中' ? 'background: rgba(251, 191, 36, 0.1); color: #fbbf24; border: 1px solid #fbbf24;' : 
              'background: rgba(239, 68, 68, 0.1); color: #ef4444; border: 1px solid #ef4444;'}">
            ${r.prediction_status || "未実行"}
          </span>
        </td>
      </tr>
    `).join("");
  }

  // 店舗データ読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(STORES_TABLE);
    const storeSelect = container.querySelector("#store-select");
    if (stores) {
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' + 
        stores.filter(s => s.active_flag).map(s => `<option value="${s.id}">${s.store_name}</option>`).join("");
    }
  }

  // 商品カテゴリ読み込み
  async function loadCategories() {
    const products = await window.aivicApi.list(PRODUCTS_TABLE);
    const categoryList = container.querySelector("#category-list");
    if (products) {
      const categories = [...new Set(products.map(p => p.product_category_id).filter(Boolean))];
      categoryList.innerHTML = categories.map(cat => 
        `<label style="display: block; margin-bottom: 5px; color: var(--text);">
          <input type="checkbox" class="category-checkbox" value="${cat}" style="margin-right: 8px;"> カテゴリ${cat}
        </label>`
      ).join("");
    }
  }

  // 初期データ読み込み
  async function loadInitialData() {
    await loadStores();
    await loadCategories();

    // 予測結果の初期表示
    const predictionResults = await window.aivicApi.list(PREDICTION_RESULTS_TABLE);
    if (predictionResults) {
      // 店舗名と商品名を結合
      const stores = await window.aivicApi.list(STORES_TABLE);
      const products = await window.aivicApi.list(PRODUCTS_TABLE);

      const enrichedResults = predictionResults.map(result => ({
        ...result,
        store_name: stores?.find(s => s.id === result.store_id)?.store_name || "",
        product_name: products?.find(p => p.id === result.product_id)?.product_name || ""
      }));

      renderPredictionResults(enrichedResults);
    }
  }

  // 季節要因スライダー
  const seasonalSlider = container.querySelector("#seasonal-factor");
  const seasonalValue = container.querySelector("#seasonal-value");
  seasonalSlider.addEventListener("input", () => {
    seasonalValue.textContent = seasonalSlider.value + "%";
  });

  // 全選択チェックボックス
  container.querySelector("#select-all-categories").addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll(".category-checkbox");
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // バリデーション関数
  function validateForm() {
    const errors = [];

    const startDate = container.querySelector("#prediction-start-date").value;
    const endDate = container.querySelector("#prediction-end-date").value;
    const stores = Array.from(container.querySelectorAll("#store-select option:checked")).map(o => o.value).filter(v => v);
    const categories = Array.from(container.querySelectorAll(".category-checkbox:checked")).map(cb => cb.value);
    const model = container.querySelector("input[name='prediction-model']:checked");
    const learningStart = container.querySelector("#learning-start-date").value;
    const learningEnd = container.querySelector("#learning-end-date").value;

    if (!startDate || !endDate) {
      errors.push("予測期間を選択してください");
    } else {
      const start = new Date(startDate);
      const end = new Date(endDate);
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      if (start < today || end < today) {
        errors.push("予測期間に過去の日付は指定できません");
      }

      const diffTime = Math.abs(end - start);
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      if (diffDays > 365) {
        errors.push("予測期間は1年以内で設定してください");
      }
    }

    if (stores.length === 0) {
      errors.push("店舗を選択してください");
    }

    if (categories.length === 0) {
      errors.push("商品カテゴリを選択してください");
    }

    if (!model) {
      errors.push("予測モデルを選択してください");
    }

    if (!learningStart || !learningEnd) {
      errors.push("学習データ期間の開始日と終了日を入力してください");
    } else if (learningStart && learningEnd && startDate && endDate) {
      const learningStartDate = new Date(learningStart);
      const learningEndDate = new Date(learningEnd);
      const predictionStartDate = new Date(startDate);
      const predictionEndDate = new Date(endDate);

      const learningDays = Math.ceil((learningEndDate - learningStartDate) / (1000 * 60 * 60 * 24));
      const predictionDays = Math.ceil((predictionEndDate - predictionStartDate) / (1000 * 60 * 60 * 24));

      if (learningDays < predictionDays) {
        errors.push("学習データ期間は予測期間以上に設定してください");
      }
    }

    return errors;
  }

  // 進捗バー制御
  function showProgress() {
    const progressContainer = container.querySelector("#progress-container");
    const progressBar = container.querySelector("#progress-bar");
    const progressText = container.querySelector("#progress-text");
    const progressPercentage = container.querySelector("#progress-percentage");
    const executeBtn = container.querySelector("#btn-execute-prediction");

    progressContainer.classList.remove("hidden");
    executeBtn.disabled = true;
    executeBtn.textContent = "処理中...";

    let progress = 0;
    const steps = [
      "データ収集中...",
      "天候データ取得中...",
      "イベントデータ取得中...",
      "学習データ準備中...",
      "AIモデル学習中...",
      "需要予測実行中...",
      "結果生成中...",
      "完了"
    ];

    const interval = setInterval(() => {
      progress += Math.random() * 15 + 5;
      if (progress > 100) progress = 100;

      progressBar.style.width = progress + "%";
      progressPercentage.textContent = Math.round(progress) + "%";

      const stepIndex = Math.floor((progress / 100) * (steps.length - 1));
      progressText.textContent = steps[stepIndex];

      if (progress >= 100) {
        clearInterval(interval);
        setTimeout(() => {
          progressContainer.classList.add("hidden");
          executeBtn.disabled = false;
          executeBtn.textContent = "AI予測実行";
          progressBar.style.width = "0%";
          progressPercentage.textContent = "0%";
          progressText.textContent = "予測処理を実行中...";
        }, 1000);
      }
    }, 200);

    return interval;
  }

  // AI予測実行
  container.querySelector("#btn-execute-prediction").addEventListener("click", async () => {
    const errors = validateForm();
    if (errors.length > 0) {
      alert(errors.join("\n"));
      return;
    }

    const progressInterval = showProgress();

    try {
      // 予測設定データ収集
      const predictionData = {
        start_date: container.querySelector("#prediction-start-date").value,
        end_date: container.querySelector("#prediction-end-date").value,
        store_ids: Array.from(container.querySelectorAll("#store-select option:checked")).map(o => o.value).filter(v => v),
        categories: Array.from(container.querySelectorAll(".category-checkbox:checked")).map(cb => cb.value),
        model: container.querySelector("input[name='prediction-model']:checked").value,
        learning_start: container.querySelector("#learning-start-date").value,
        learning_end: container.querySelector("#learning-end-date").value,
        seasonal_factor: parseInt(container.querySelector("#seasonal-factor").value),
        accuracy_threshold: parseFloat(container.querySelector("#accuracy-threshold").value)
      };

      // 模擬的な予測結果生成
      const stores = await window.aivicApi.list(STORES_TABLE);
      const products = await window.aivicApi.list(PRODUCTS_TABLE);

      if (!stores || !products) {
        throw new Error("店舗または商品データの取得に失敗しました");
      }

      const results = [];
      const selectedStores = stores.filter(s => predictionData.store_ids.includes(s.id));
      const selectedProducts = products.filter(p => predictionData.categories.includes(p.product_category_id));

      for (const store of selectedStores) {
        for (const product of selectedProducts) {
          const result = await window.aivicApi.save(PREDICTION_RESULTS_TABLE, {
            store_id: store.id,
            product_id: product.id,
            prediction_date: predictionData.start_date,
            predicted_quantity: Math.floor(Math.random() * 100) + 10,
            prediction_accuracy: Math.floor(Math.random() * 30) + 70,
            recommended_order_quantity: Math.floor(Math.random() * 80) + 15,
            prediction_model_version: predictionData.model + "_v1.0",
            prediction_status: "完了",
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString()
          });

          if (result) {
            results.push({
              ...result,
              store_name: store.store_name,
              product_name: product.product_name
            });
          }
        }
      }

      // 結果表示
      setTimeout(() => {
        renderPredictionResults(results);
        alert("AI需要予測処理が完了しました。" + results.length + "件の予測結果を生成しました。");
      }, 2000);

    } catch (error) {
      clearInterval(progressInterval);
      container.querySelector("#progress-container").classList.add("hidden");
      container.querySelector("#btn-execute-prediction").disabled = false;
      container.querySelector("#btn-execute-prediction").textContent = "AI予測実行";
      alert("AI予測実行に失敗しました: " + error.message);
    }
  });

  // 天候データ取込
  container.querySelector("#btn-import-weather").addEventListener("click", async () => {
    try {
      const startDate = container.querySelector("#prediction-start-date").value;
      const endDate = container.querySelector("#prediction-end-date").value;

      if (!startDate || !endDate) {
        alert("予測期間を設定してから天候データを取り込んでください");
        return;
      }

      // 模擬的な天候データ生成
      const stores = await window.aivicApi.list(STORES_TABLE);
      if (!stores) {
        throw new Error("店舗データの取得に失敗しました");
      }

      let importCount = 0;
      const start = new Date(startDate);
      const end = new Date(endDate);

      for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
        for (const store of stores.slice(0, 3)) { // 最初の3店舗のみ
          const weatherData = await window.aivicApi.save(WEATHER_DATA_TABLE, {
            store_id: store.id,
            observation_date: d.toISOString().split('T')[0],
            weather: ["晴れ", "曇り", "雨", "雪"][Math.floor(Math.random() * 4)],
            max_temperature: Math.floor(Math.random() * 20) + 10,
            min_temperature: Math.floor(Math.random() * 15) + 5,
            avg_temperature: Math.floor(Math.random() * 18) + 8,
            precipitation: Math.floor(Math.random() * 50),
            humidity: Math.floor(Math.random() * 40) + 40,
            wind_speed: Math.floor(Math.random() * 10) + 1,
            data_type: "予報値",
            data_source: "気象庁API",
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString()
          });

          if (weatherData) importCount++;
        }
      }

      alert("天候データの取込が完了しました。" + importCount + "件のデータを取り込みました。");

    } catch (error) {
      alert("天候データの取得に失敗しました。データソースの設定を確認してください。");
    }
  });

  // イベントデータ取込
  container.querySelector("#btn-import-events").addEventListener("click", async () => {
    try {
      const stores = await window.aivicApi.list(STORES_TABLE);
      if (!stores) {
        throw new Error("店舗データの取得に失敗しました");
      }

      const events = [
        { name: "夏祭り", type: "祭り", impact: "大" },
        { name: "コンサート", type: "コンサート", impact: "中" },
        { name: "スポーツ大会", type: "スポーツ", impact: "小" }
      ];

      let importCount = 0;
      for (const store of stores.slice(0, 2)) {
        for (const event of events) {
          const eventData = await window.aivicApi.save(EVENT_DATA_TABLE, {
            store_id: store.id,
            event_name: event.name,
            event_type: event.type,
            start_datetime: new Date(Date.now() + Math.random() * 30 * 24 * 60 * 60 * 1000).toISOString(),
            end_datetime: new Date(Date.now() + Math.random() * 30 * 24 * 60 * 60 * 1000 + 24 * 60 * 60 * 1000).toISOString(),
            expected_visitors: Math.floor(Math.random() * 10000) + 1000,
            impact_level: event.impact,
            location: "地域イベント会場",
            distance_from_store: Math.floor(Math.random() * 5000) + 100,
            active_flag: true,
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString(),
            created_by: "システム自動取得",
            updated_by: "システム自動取得"
          });

          if (eventData) importCount++;
        }
      }

      alert("イベントデータの取込が完了しました。" + importCount + "件のデータを取り込みました。");

    } catch (error) {
      alert("イベントデータの取込に失敗しました。ファイル形式を確認してください。");
    }
  });

  // 初期化
  loadInitialData();

  // デフォルト日付設定
  const today = new Date();
  const tomorrow = new Date(today);
  tomorrow.setDate(tomorrow.getDate() + 1);
  const nextWeek = new Date(today);
  nextWeek.setDate(nextWeek.getDate() + 7);
  const lastMonth = new Date(today);
  lastMonth.setMonth(lastMonth.getMonth() - 1);

  container.querySelector("#prediction-start-date").value = tomorrow.toISOString().split('T')[0];
  container.querySelector("#prediction-end-date").value = nextWeek.toISOString().split('T')[0];
  container.querySelector("#learning-start-date").value = lastMonth.toISOString().split('T')[0];
  container.querySelector("#learning-end-date").value = today.toISOString().split('T')[0];
}

function(container, apiUrl, tables) {
