  // 小計の更新
  function updateSubtotals() {
    const rows = container.querySelectorAll('#product-list tr[data-id]');
    rows.forEach(row => {
      const productId = row.dataset.id;
      const product = allProducts.find(p => p.商品ID === productId);
      const quantityInput = row.querySelector('.quantity-input');
      const subtotalCell = row.querySelector('.subtotal');

      if (product && quantityInput && subtotalCell) {
        const quantity = parseInt(quantityInput.value) || 0;
        const subtotal = (product.単価 || 0) * quantity;
        subtotalCell.textContent = `¥${subtotal.toLocaleString()}`;
      }
    });
  }

  // 発注総額の更新
  function updateTotalAmount() {
    let total = 0;
    selectedProducts.forEach(item => {
      total += (item.単価 || 0) * (item.発注数量 || 0);
