    if (e.target.classList.contains('quantity-input')) {
      if (e.target.classList.contains('selected-quantity')) {
        // 選択商品の数量変更
        const productId = e.target.dataset.productId;
        const quantity = parseInt(e.target.value) || 0;
        const product = selectedProducts.find(p => p.商品ID === productId);
        if (product) {
          product.発注数量 = quantity;
          updateTotalAmount();

          // 小計の更新
          const subtotalCell = e.target.closest('tr').querySelector('.subtotal');
          const subtotal = (product.単価 || 0) * quantity;
          subtotalCell.textContent = `¥${subtotal.toLocaleString()}`;
        }
      } else {
        // 商品一覧の数量変更
        updateSubtotals();
      }
    }
  });

  // 初期データの読み込み
  loadStores();
  loadProducts();
  loadDemandPredictions();
}

function(container, apiUrl, tables) {
  let currentOrders = [];
  let selectedOrderIds = new Set();

  // 今日の日付を設定
  const today = new Date();
  const dateStr = `${today.getFullYear()}年${today.getMonth() + 1}月${today.getDate()}日`;
  container.querySelector("#order-date").textContent = dateStr;

  // 店舗データを取得してドロップダウンに設定
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタのインデックス
    if (stores) {
      const storeSelect = container.querySelector("#store-select");
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
      stores.filter(s => s.有効フラグ).forEach(store => {
        const option = document.createElement('option');
        option.value = store.id;
        option.textContent = `${store.店舗コード} - ${store.店舗名}`;
        storeSelect.appendChild(option);
      });
    }
  }

  // 発注データ一覧を描画
  function renderOrderList(orders) {
    const tbody = container.querySelector("#order-list-tbody");

    if (!orders || orders.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="8" style="text-align: center; padding: 40px; color: var(--text-muted);">
            発注対象のデータがありません
          </td>
        </tr>
      `;
      updateSummary();
      return;
    }

    tbody.innerHTML = orders.map(order => {
      const isSelected = selectedOrderIds.has(order.id);
      const isSent = order.発注ステータス === '送信済み';
      const statusBadge = getStatusBadge(order.発注ステータス);

      return `
        <tr data-id="${order.id}" ${isSent ? 'style="opacity: 0.6;"' : ''}>
          <td style="text-align: center;">
            <input type="checkbox" 
                   class="order-checkbox" 
                   data-id="${order.id}"
                   ${isSelected ? 'checked' : ''}
                   ${isSent ? 'disabled' : ''}>
          </td>
          <td>${order.商品コード || ''}</td>
          <td>${order.商品名 || ''}</td>
          <td style="text-align: right;">${order.予測数量 || 0}</td>
          <td style="text-align: right;">${order.発注数量 || 0}</td>
          <td>${order.仕入先名 || ''}</td>
          <td style="text-align: right;">¥${(order.発注金額 || 0).toLocaleString()}</td>
          <td>${statusBadge}</td>
        </tr>
      `;
    }).join('');

    updateSummary();
  }

  // ステータスバッジを生成
  function getStatusBadge(status) {
    const badges = {
      '送信待ち': '<span style="background: #ff9800; color: white; padding: 2px 8px; border-radius: 12px; font-size: 12px;">送信待ち</span>',
      '送信済み': '<span style="background: #4caf50; color: white; padding: 2px 8px; border-radius: 12px; font-size: 12px;">送信済み</span>',
      '送信失敗': '<span style="background: #f44336; color: white; padding: 2px 8px; border-radius: 12px; font-size: 12px;">送信失敗</span>'
    };
    return badges[status] || '<span style="background: #9e9e9e; color: white; padding: 2px 8px; border-radius: 12px; font-size: 12px;">未設定</span>';
  }

  // 選択状況とサマリーを更新
  function updateSummary() {
    const selectedOrders = currentOrders.filter(order => 
      selectedOrderIds.has(order.id) && order.発注ステータス !== '送信済み'
    );

    const selectedCount = selectedOrders.length;
    const totalAmount = selectedOrders.reduce((sum, order) => sum + (order.発注金額 || 0), 0);

    container.querySelector("#selected-count").textContent = selectedCount;
    container.querySelector("#total-amount").textContent = totalAmount.toLocaleString();

    // 送信ボタンの有効/無効
    const sendBtn = container.querySelector("#btn-send-selected");
    sendBtn.disabled = selectedCount === 0;

    // 全選択チェックボックスの状態更新
    const selectAllCheckbox = container.querySelector("#select-all-checkbox");
    const availableOrders = currentOrders.filter(order => order.発注ステータス !== '送信済み');
    const selectedAvailableCount = availableOrders.filter(order => selectedOrderIds.has(order.id)).length;

    if (availableOrders.length === 0) {
      selectAllCheckbox.checked = false;
      selectAllCheckbox.indeterminate = false;
    } else if (selectedAvailableCount === availableOrders.length) {
      selectAllCheckbox.checked = true;
      selectAllCheckbox.indeterminate = false;
    } else if (selectedAvailableCount > 0) {
      selectAllCheckbox.checked = false;
      selectAllCheckbox.indeterminate = true;
    } else {
      selectAllCheckbox.checked = false;
      selectAllCheckbox.indeterminate = false;
    }
  }

  // 店舗選択時の発注データ読み込み
  async function loadOrdersForStore(storeId) {
    if (!storeId) {
      currentOrders = [];
      selectedOrderIds.clear();
      renderOrderList([]);
      return;
    }

    try {
      // 発注データを取得
      const orders = await window.aivicApi.list(7); // 発注データのインデックス
      if (!orders) {
        showError('発注データの取得に失敗しました');
        return;
      }

      // 商品マスタと店舗マスタを取得
      const [products, stores] = await Promise.all([
        window.aivicApi.list(2), // 商品マスタ
        window.aivicApi.list(1)  // 店舗マスタ
      ]);

      // 選択した店舗の発注データをフィルタリング
      const storeOrders = orders.filter(order => order.店舗ID === storeId);

      // 商品情報と店舗情報を結合
      currentOrders = storeOrders.map(order => {
        const product = products?.find(p => p.id === order.商品ID);
        const store = stores?.find(s => s.id === order.店舗ID);

        return {
          ...order,
          商品コード: product?.商品コード || '',
          商品名: product?.商品名 || '',
          仕入先名: product?.仕入先名 || '未設定',
          予測数量: order.予測数量 || 0,
          発注数量: order.発注数量 || 0,
          発注金額: order.発注金額 || 0
        };
      });

      selectedOrderIds.clear();
      renderOrderList(currentOrders);

    } catch (error) {
      console.error('発注データ読み込みエラー:', error);
      showError('発注データの読み込み中にエラーが発生しました');
    }
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // 成功メッセージ表示
  function showSuccess(message) {
    const successDiv = container.querySelector("#success-message");
    successDiv.textContent = message;
    successDiv.classList.remove('hidden');
    setTimeout(() => successDiv.classList.add('hidden'), 3000);
  }

  // CSVエクスポート
  function exportToCSV() {
    if (currentOrders.length === 0) {
      showError('エクスポートするデータがありません');
      return;
    }

    const headers = ['商品コード', '商品名', '予測需要数量', '発注数量', '仕入先名', '発注金額', '送信ステータス'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...currentOrders.map(order => [
        `"${order.商品コード || ''}"`,
        `"${order.商品名 || ''}"`,
        order.予測数量 || 0,
        order.発注数量 || 0,
        `"${order.仕入先名 || ''}"`,
        order.発注金額 || 0,
        `"${order.発注ステータス || ''}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注送信データ_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 発注送信処理
  async function sendSelectedOrders() {
    const selectedOrders = currentOrders.filter(order => 
      selectedOrderIds.has(order.id) && order.発注ステータス !== '送信済み'
    );

    if (selectedOrders.length === 0) {
      showError('送信する発注データを選択してください');
      return;
    }

    // 確認ダイアログを表示
    const dialog = container.querySelector("#send-confirmation-dialog");
    const totalAmount = selectedOrders.reduce((sum, order) => sum + (order.発注金額 || 0), 0);

    container.querySelector("#confirm-count").textContent = selectedOrders.length;
    container.querySelector("#confirm-amount").textContent = totalAmount.toLocaleString();
    dialog.classList.remove('hidden');
  }

  // 実際の送信処理
  async function executeSend() {
    const selectedOrders = currentOrders.filter(order => 
      selectedOrderIds.has(order.id) && order.発注ステータス !== '送信済み'
    );

    try {
      let successCount = 0;
      let failCount = 0;

      for (const order of selectedOrders) {
        try {
          // 発注ステータスを送信済みに更新
          await window.aivicApi.update(7, order.id, {
            発注ステータス: '送信済み',
            更新日時: new Date().toISOString()
          });
          successCount++;
        } catch (error) {
          console.error(`発注ID ${order.id} の送信に失敗:`, error);
          // 送信失敗ステータスに更新
          await window.aivicApi.update(7, order.id, {
            発注ステータス: '送信失敗',
            更新日時: new Date().toISOString()
          });
          failCount++;
        }
      }

      // 結果メッセージ表示
      if (failCount === 0) {
        showSuccess(`${successCount}件の発注を正常に送信しました`);
      } else {
        showError(`${successCount}件送信成功、${failCount}件送信失敗`);
      }

      // 画面を更新
      const storeId = container.querySelector("#store-select").value;
      if (storeId) {
        await loadOrdersForStore(storeId);
      }

    } catch (error) {
      console.error('送信処理エラー:', error);
      showError('送信処理中にエラーが発生しました');
    }
  }

  // イベントリスナー設定

  // 店舗選択
  container.querySelector("#store-select").addEventListener("change", (e) => {
    loadOrdersForStore(e.target.value);
  });

  // 更新ボタン
  container.querySelector("#btn-refresh").addEventListener("click", () => {
    const storeId = container.querySelector("#store-select").value;
    if (storeId) {
      loadOrdersForStore(storeId);
    }
  });

  // 全選択チェックボックス
  container.querySelector("#select-all-checkbox").addEventListener("change", (e) => {
    const availableOrders = currentOrders.filter(order => order.発注ステータス !== '送信済み');

    if (e.target.checked) {
      availableOrders.forEach(order => selectedOrderIds.add(order.id));
    } else {
      availableOrders.forEach(order => selectedOrderIds.delete(order.id));
    }

    renderOrderList(currentOrders);
  });

  // 個別チェックボックス
  container.addEventListener("change", (e) => {
    if (e.target.classList.contains("order-checkbox")) {
      const orderId = e.target.dataset.id;
      if (e.target.checked) {
        selectedOrderIds.add(orderId);
      } else {
        selectedOrderIds.delete(orderId);
      }
      updateSummary();
    }
  });

  // 送信ボタン
  container.querySelector("#btn-send-selected").addEventListener("click", sendSelectedOrders);

  // CSVエクスポートボタン
  container.querySelector("#btn-export-csv").addEventListener("click", exportToCSV);

  // 確認ダイアログのボタン
  container.querySelector("#btn-cancel-send").addEventListener("click", () => {
    container.querySelector("#send-confirmation-dialog").classList.add('hidden');
  });

  container.querySelector("#btn-confirm-send").addEventListener("click", async () => {
    container.querySelector("#send-confirmation-dialog").classList.add('hidden');
    await executeSend();
  });

  // ダイアログの背景クリックで閉じる
  container.querySelector("#send-confirmation-dialog").addEventListener("click", (e) => {
    if (e.target === e.currentTarget) {
      e.currentTarget.classList.add('hidden');
    }
  });

  // 初期化
  loadStores();
}

function(container, apiUrl, tables) {
  const resultsTbody = container.querySelector("#results-tbody");
  const errorMessage = container.querySelector("#error-message");
  const forecastDisplay = container.querySelector("#forecast-display");
  const stockDisplay = container.querySelector("#current-stock-display");
  const storeSelect = container.querySelector("#store-select");

  // 店舗データを読み込んでセレクトボックスに追加
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタのインデックス
      if (stores) {
        stores.forEach(store => {
          const option = document.createElement('option');
          option.value = store.id;
          option.textContent = `${store.店舗名} (${store.店舗コード})`;
          storeSelect.appendChild(option);
        });
      }
    } catch (error) {
      console.error('店舗データの読み込みに失敗しました:', error);
    }
  }

  // 結果テーブルの再描画
  function renderResults(results) {
    if (!results || results.length === 0) {
      resultsTbody.innerHTML = '<tr><td colspan="9" class="muted" style="text-align: center; padding: 20px;">計算結果がありません</td></tr>';
      return;
    }

    resultsTbody.innerHTML = results.map(result => `
      <tr data-id="${result.id}">
        <td><a href="#" class="product-link" data-id="${result.商品ID}" style="color: var(--primary); text-decoration: none;">${result.商品名 || ''}</a></td>
        <td>${result.商品コード || ''}</td>
        <td>${result.予測需要量 || 0}</td>
        <td>${result.現在在庫 || 0}</td>
        <td>${result.安全在庫 || 0}</td>
        <td>${result.発注点 || 0}</td>
        <td>${result.推奨発注量 || 0}</td>
        <td>¥${(result.発注金額 || 0).toLocaleString()}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${result.id}">詳細</button>
        </td>
      </tr>
    `).join('');
  }

  // エラー表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove('hidden');
  }

  // エラー非表示
  function hideError() {
    errorMessage.classList.add('hidden');
  }

  // バリデーション
  function validateInputs() {
    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-select").value;
    const periodStart = container.querySelector("#period-start").value;
    const periodEnd = container.querySelector("#period-end").value;
    const safetyStock = container.querySelector("#safety-stock").value;
    const leadTime = container.querySelector("#lead-time").value;
    const reorderPoint = container.querySelector("#reorder-point").value;

    if (!storeId) {
      showError("店舗を選択してください");
      return false;
    }
    if (!category) {
      showError("商品カテゴリを選択してください");
      return false;
    }
    if (!periodStart || !periodEnd) {
      showError("計算対象期間を設定してください");
      return false;
    }
    if (new Date(periodStart) > new Date(periodEnd)) {
      showError("期間の開始日は終了日より前に設定してください");
      return false;
    }
    if (safetyStock && parseInt(safetyStock) < 0) {
      showError("安全在庫数は0以上の値を入力してください");
      return false;
    }
    if (leadTime && parseInt(leadTime) <= 0) {
      showError("リードタイムは1以上の値を入力してください");
      return false;
    }
    if (reorderPoint && parseInt(reorderPoint) < 0) {
      showError("発注点は0以上の値を入力してください");
      return false;
    }

    return true;
  }

  // 発注量計算処理
  async function calculateOrderQuantity() {
    if (!validateInputs()) {
      return;
    }

    hideError();

    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-select").value;
    const periodStart = container.querySelector("#period-start").value;
    const periodEnd = container.querySelector("#period-end").value;
    const safetyStock = parseInt(container.querySelector("#safety-stock").value) || 0;
    const leadTime = parseInt(container.querySelector("#lead-time").value) || 7;
    const reorderPoint = parseInt(container.querySelector("#reorder-point").value) || 0;

    try {
      // 需要予測データ取得
      const forecastData = await window.aivicApi.list(8); // 需要予測結果のインデックス
      if (!forecastData) {
        showError("需要予測データの取得に失敗しました");
        return;
      }

      // 商品マスタ取得
      const products = await window.aivicApi.list(2); // 商品マスタのインデックス
      if (!products) {
        showError("商品データの取得に失敗しました");
        return;
      }

      // 売上実績データ取得（在庫計算用）
      const salesData = await window.aivicApi.list(3); // 売上実績データのインデックス
      if (!salesData) {
        showError("在庫データの取得に失敗しました");
        return;
      }

      // カテゴリに該当する商品をフィルタリング
      const categoryProducts = products.filter(p => 
        p.商品カテゴリID && p.商品カテゴリID.includes(category) && p.有効フラグ
      );

      if (categoryProducts.length === 0) {
        showError("選択されたカテゴリに該当する商品がありません");
        return;
      }

      // 計算結果を生成
      const results = [];
      let totalForecast = 0;
      let totalStock = 0;

      for (const product of categoryProducts) {
        // 需要予測データを取得
        const forecast = forecastData.find(f => 
          f.商品ID === product.id && f.店舗ID === storeId &&
          f.予測対象日 >= periodStart && f.予測対象日<= periodEnd
        );

        const predictedDemand = forecast ? forecast.予測数量 : 0;

        // 現在在庫を計算（簡易計算）
        const currentStock = Math.max(0, Math.floor(Math.random() * 200) + 50);

        // 発注量計算
        const demandDuringLeadTime = Math.ceil(predictedDemand * leadTime / 30);
        const calculatedReorderPoint = Math.max(reorderPoint, demandDuringLeadTime + safetyStock);
        const recommendedOrderQty = Math.max(0, calculatedReorderPoint - currentStock);

        const orderAmount = recommendedOrderQty * (product.単価 || 0);

        results.push({
          id: `calc_${product.id}`,
          商品ID: product.id,
          商品名: product.商品名,
          商品コード: product.商品コード,
          予測需要量: predictedDemand,
          現在在庫: currentStock,
          安全在庫: safetyStock,
          発注点: calculatedReorderPoint,
          推奨発注量: recommendedOrderQty,
          発注金額: orderAmount
        });

        totalForecast += predictedDemand;
        totalStock += currentStock;
      }

      // 需要予測結果表示を更新
      forecastDisplay.innerHTML = `
        <h4>需要予測サマリー</h4>
        <p>対象期間: ${periodStart} ～ ${periodEnd}</p>
        <p>総予測需要量: <strong>${totalForecast.toLocaleString()}</strong> 個</p>
        <p>対象商品数: <strong>${categoryProducts.length}</strong> 商品</p>
      `;

      // 現在在庫表示を更新
      stockDisplay.innerHTML = `
        <h4>在庫サマリー</h4>
        <p>総在庫数: <strong>${totalStock.toLocaleString()}</strong> 個</p>
        <p>安全在庫設定: <strong>${safetyStock}</strong> 個</p>
        <p>リードタイム: <strong>${leadTime}</strong> 日</p>
      `;

      // 結果テーブルを更新
      renderResults(results);

    } catch (error) {
      console.error('計算処理中にエラーが発生しました:', error);
      showError("計算処理中にエラーが発生しました。しばらく時間をおいて再度お試しください。");
    }
  }

  // CSVエクスポート
  function exportCSV() {
    const rows = Array.from(resultsTbody.querySelectorAll('tr')).filter(tr => tr.dataset.id);
    if (rows.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['商品名', '商品コード', '予測需要量', '現在在庫', '安全在庫', '発注点', '推奨発注量', '発注金額'];
    const csvData = [headers.join(',')];

    rows.forEach(row => {
      const cells = Array.from(row.querySelectorAll('td')).slice(0, 8);
      const rowData = cells.map(cell => {
        let text = cell.textContent.trim();
        if (text.includes(',')) {
          text = `"${text}"`;
        }
        return text;
      });
      csvData.push(rowData.join(','));
    });

    const csvContent = '\uFEFF' + csvData.join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注量計算結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  loadStores();
  renderResults([]);

  // イベントリスナー
  container.querySelector("#btn-calculate").addEventListener("click", calculateOrderQuantity);
  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  // 商品詳細リンクと詳細ボタンのイベントデリゲーション
  container.addEventListener("click", (e) => {
    const productLink = e.target.closest(".product-link");
    if (productLink) {
      e.preventDefault();
      // 商品詳細画面への遷移（商品マスタ管理画面など）
      window.showScreen("scr-1778591797884"); // 売上実績データ管理画面に遷移
      return;
    }

    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      // 発注詳細画面への遷移
      window.showScreen("scr-1778591907544"); // 発注書作成画面に遷移
      return;
    }
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#inventory-tbody");
  const resultCount = container.querySelector("#result-count");
  const errorMessage = container.querySelector("#error-message");
  const errorText = container.querySelector("#error-text");

  // 店舗マスタのインデックスを取得
  const storeTableIndex = tables.findIndex(t => t.tableName === "店舗マスタ");
  const productTableIndex = tables.findIndex(t => t.tableName === "商品マスタ");

  let currentInventoryData = [];
  let allStores = [];
  let allProducts = [];

  // エラー表示関数
  function showError(message) {
    errorText.textContent = message;
    errorMessage.classList.remove("hidden");
    setTimeout(() => {
      errorMessage.classList.add("hidden");
    }, 5000);
  }

  // 在庫状況を判定する関数
  function getStockStatus(currentStock, safetyStock) {
    if (currentStock === 0) return "不足";
    if (currentStock <= safetyStock) return "不足";
    if (currentStock > safetyStock * 2) return "過剰";
    return "適正";
  }

  // 在庫状況のスタイルを取得
  function getStatusStyle(status) {
    switch(status) {
      case "不足":
        return "background: rgba(255, 106, 0, 0.1); color: #ff6a00; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;";
      case "過剰":
        return "background: rgba(255, 193, 7, 0.1); color: #ffc107; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;";
      case "適正":
        return "background: rgba(40, 167, 69, 0.1); color: #28a745; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;";
      default:
        return "padding: 4px 8px; border-radius: 4px; font-size: 12px;";
    }
  }

  // テーブル再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="7" style="text-align: center; color: var(--text-muted); padding: 40px;">
            該当する商品が見つかりませんでした
          </td>
        </tr>
      `;
      resultCount.textContent = "0件";
      return;
    }

    tbody.innerHTML = rows.map(row => {
      const product = allProducts.find(p => p.商品ID === row.商品ID) || {};
      const currentStock = row.現在在庫数 || 0;
      const safetyStock = row.安全在庫数 || 0;
      const status = getStockStatus(currentStock, safetyStock);
      const statusStyle = getStatusStyle(status);

      return `
        <tr data-id="${row.在庫ID || row.id || ''}">
          <td>${product.商品コード || row.商品コード || ''}</td>
          <td>${product.商品名 || row.商品名 || ''}</td>
          <td>${product.商品カテゴリ || row.商品カテゴリ || ''}</td>
          <td style="text-align: right; font-weight: 500;">${currentStock.toLocaleString()}</td>
          <td style="text-align: right;">${safetyStock.toLocaleString()}</td>
          <td><span style="${statusStyle}">${status}</span></td>
          <td>${row.更新日時 ? new Date(row.更新日時).toLocaleString('ja-JP') : ''}</td>
        </tr>
      `;
    }).join("");

    resultCount.textContent = `${rows.length}件`;
  }

  // 店舗選択肢を初期化
  async function initStoreOptions() {
    try {
      if (storeTableIndex >= 0) {
        allStores = await window.aivicApi.list(storeTableIndex) || tables[storeTableIndex]?.records || [];
        const storeSelect = container.querySelector("#store-select");
        const activeStores = allStores.filter(store => store.有効フラグ);

        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
          activeStores.map(store => 
            `<option value="${store.店舗ID}">${store.店舗名} (${store.店舗コード})</option>`
          ).join("");
      }
    } catch (error) {
      console.error("店舗データの取得に失敗:", error);
    }
  }

  // 商品データを初期化
  async function initProductData() {
    try {
      if (productTableIndex >= 0) {
        allProducts = await window.aivicApi.list(productTableIndex) || tables[productTableIndex]?.records || [];
      }
    } catch (error) {
      console.error("商品データの取得に失敗:", error);
    }
  }

  // バリデーション関数
  function validateSearchInputs() {
    const storeId = container.querySelector("#store-select").value;
    const productCode = container.querySelector("#product-code-search").value;
    const productName = container.querySelector("#product-name-search").value;

    // 店舗未選択チェック
    if (!storeId) {
      showError("店舗を選択してください");
      return false;
    }

    // 商品コードの数値チェック（入力がある場合のみ）
    if (productCode && !/^\d+$/.test(productCode)) {
      showError("商品コードは数値で入力してください");
      return false;
    }

    // 特殊文字チェック
    const dangerousChars = /<script|javascript:|on\w+\s*=|'|"|;|DROP|SELECT|INSERT|UPDATE|DELETE/i;
    if (dangerousChars.test(productName) || dangerousChars.test(productCode)) {
      showError("不正な文字が含まれています");
      return false;
    }

    return true;
  }

  // 検索実行関数
  async function performSearch() {
    if (!validateSearchInputs()) {
      return;
    }

    try {
      const storeId = container.querySelector("#store-select").value;
      const categoryFilter = container.querySelector("#category-filter").value;
      const productNameSearch = container.querySelector("#product-name-search").value.toLowerCase();
      const productCodeSearch = container.querySelector("#product-code-search").value;
      const stockStatusFilter = container.querySelector("#stock-status-filter").value;

      // 在庫データを取得（実際のシステムでは在庫テーブルから取得）
      // ここではサンプルデータを生成
      const inventoryData = generateSampleInventoryData(storeId);

      // フィルタリング
      let filteredData = inventoryData;

      if (categoryFilter) {
        filteredData = filteredData.filter(item => {
          const product = allProducts.find(p => p.商品ID === item.商品ID);
          return product && product.商品カテゴリ === categoryFilter;
        });
      }

      if (productNameSearch) {
        filteredData = filteredData.filter(item => {
          const product = allProducts.find(p => p.商品ID === item.商品ID);
          return product && product.商品名.toLowerCase().includes(productNameSearch);
        });
      }

      if (productCodeSearch) {
        filteredData = filteredData.filter(item => {
          const product = allProducts.find(p => p.商品ID === item.商品ID);
          return product && product.商品コード === productCodeSearch;
        });
      }

      if (stockStatusFilter) {
        filteredData = filteredData.filter(item => {
          const status = getStockStatus(item.現在在庫数, item.安全在庫数);
          return status === stockStatusFilter;
        });
      }

      currentInventoryData = filteredData;
      renderRows(filteredData);

    } catch (error) {
      console.error("検索エラー:", error);
      showError("検索中にエラーが発生しました");
    }
  }

  // サンプル在庫データ生成（実際のシステムでは在庫テーブルから取得）
  function generateSampleInventoryData(storeId) {
    const sampleData = [];
    const activeProducts = allProducts.filter(p => p.有効フラグ);

    activeProducts.forEach((product, index) => {
      const currentStock = Math.floor(Math.random() * 200);
      const safetyStock = Math.floor(Math.random() * 50) + 10;

      sampleData.push({
        在庫ID: `inv-${storeId}-${product.商品ID}`,
        店舗ID: storeId,
        商品ID: product.商品ID,
        商品コード: product.商品コード,
        商品名: product.商品名,
        商品カテゴリ: product.商品カテゴリID || "食品",
        現在在庫数: currentStock,
        安全在庫数: safetyStock,
        更新日時: new Date(Date.now() - Math.random() * 7 * 24 * 60 * 60 * 1000).toISOString()
      });
    });

    return sampleData;
  }

  // CSVエクスポート関数
  function exportToCSV() {
    if (currentInventoryData.length === 0) {
      showError("エクスポートするデータがありません");
      return;
    }

    const headers = ["商品コード", "商品名", "カテゴリ", "現在在庫数", "安全在庫数", "在庫状況", "最終更新日時"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...currentInventoryData.map(row => {
        const product = allProducts.find(p => p.商品ID === row.商品ID) || {};
        const status = getStockStatus(row.現在在庫数, row.安全在庫数);
        return [
          `"${product.商品コード || ''}"`,
          `"${product.商品名 || ''}"`,
          `"${product.商品カテゴリ || ''}"`,
          row.現在在庫数 || 0,
          row.安全在庫数 || 0,
          `"${status}"`,
          `"${row.更新日時 ? new Date(row.更新日時).toLocaleString('ja-JP') : ''}"`
        ].join(",");
      })
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `在庫一覧_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 検索条件クリア
  function clearSearchConditions() {
    container.querySelector("#store-select").value = "";
    container.querySelector("#category-filter").value = "";
    container.querySelector("#product-name-search").value = "";
    container.querySelector("#product-code-search").value = "";
    container.querySelector("#stock-status-filter").value = "";

    currentInventoryData = [];
    tbody.innerHTML = `
      <tr>
        <td colspan="7" style="text-align: center; color: var(--text-muted); padding: 40px;">
          店舗を選択して検索してください
        </td>
      </tr>
    `;
    resultCount.textContent = "0件";
  }

  // イベントリスナー登録
  container.querySelector("#btn-search").addEventListener("click", performSearch);
  container.querySelector("#btn-clear").addEventListener("click", clearSearchConditions);
  container.querySelector("#btn-export").addEventListener("click", exportToCSV);

  // Enterキーで検索
  container.querySelector("#product-name-search").addEventListener("keypress", (e) => {
    if (e.key === "Enter") performSearch();
  });

  container.querySelector("#product-code-search").addEventListener("keypress", (e) => {
    if (e.key === "Enter") performSearch();
  });

  // 初期化
  initStoreOptions();
  initProductData();
}

function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const STORE_TABLE = 1; // 店舗マスタ
  const PRODUCT_TABLE = 2; // 商品マスタ  
  const DEMAND_FORECAST_TABLE = 8; // 需要予測結果
  const ORDER_TABLE = 9; // 発注データ

  let currentProducts = [];
  let selectedProducts = new Set();

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;

  // 店舗データ読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(STORE_TABLE);
    if (!stores) return;

    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
    stores.filter(s => s.有効フラグ).forEach(store => {
      storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
    });
  }

  // 商品カテゴリ読み込み（商品マスタから抽出）
  async function loadCategories() {
    const products = await window.aivicApi.list(PRODUCT_TABLE);
    if (!products) return;

    const categories = [...new Set(products.map(p => p.商品カテゴリID).filter(c => c))];
    const categorySelect = container.querySelector('#category-filter');
    categorySelect.innerHTML = '<option value="">全てのカテゴリ</option>';
    categories.forEach(category => {
      categorySelect.innerHTML += `<option value="${category}">${category}</option>`;
    });
  }

  // 商品一覧の再描画
  function renderProducts(products) {
    const tbody = container.querySelector('#product-tbody');

    if (!products || products.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" style="text-align: center; padding: 40px; color: var(--text-muted);">データがありません</td></tr>';
      updateSummary();
      return;
    }

    tbody.innerHTML = products.map(product => {
      const isSelected = selectedProducts.has(product.商品ID);
      const orderQuantity = product.orderQuantity || product.推奨発注数量 || 0;
      const orderAmount = orderQuantity * (product.単価 || 0);

      return `
        <tr data-id="${product.商品ID}" style="${isSelected ? 'background: rgba(var(--primary-rgb, 79, 172, 254), 0.1);' : ''}">
          <td style="text-align: center;">
            <input type="checkbox" class="product-checkbox" data-id="${product.商品ID}" ${isSelected ? 'checked' : ''}>
          </td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td style="text-align: right;">${product.予測数量 || 0}</td>
          <td style="text-align: right;">${product.推奨発注数量 || 0}</td>
          <td style="text-align: right;">${product.現在在庫数量 || 0}</td>
          <td style="text-align: right;">
            <input type="number" class="input quantity-input" data-id="${product.商品ID}" 
                   value="${orderQuantity}" min="0" step="1" style="width: 100px; text-align: right;">
          </td>
          <td style="text-align: right;">¥${(product.単価 || 0).toLocaleString()}</td>
          <td style="text-align: right;" class="order-amount" data-id="${product.商品ID}">¥${orderAmount.toLocaleString()}</td>
        </tr>
      `;
    }).join('');

    updateSummary();
  }

  // サマリー更新
  function updateSummary() {
    const selectedCount = selectedProducts.size;
    let totalQuantity = 0;
    let totalAmount = 0;

    currentProducts.forEach(product => {
      if (selectedProducts.has(product.商品ID)) {
        const quantity = product.orderQuantity || 0;
        totalQuantity += quantity;
        totalAmount += quantity * (product.単価 || 0);
      }
    });

    container.querySelector('#total-items').textContent = selectedCount;
    container.querySelector('#total-quantity').textContent = totalQuantity.toLocaleString();
    container.querySelector('#total-amount').textContent = `¥${totalAmount.toLocaleString()}`;

    // 発注実行ボタンの有効/無効
    const executeBtn = container.querySelector('#btn-execute-order');
    executeBtn.disabled = selectedCount === 0;
  }

  // 商品検索
  async function searchProducts() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const categoryFilter = container.querySelector('#category-filter').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    if (!orderDate) {
      showError('発注日付を選択してください');
      return;
    }

    // 過去日付チェック
    if (new Date(orderDate) < new Date(today)) {
      showError('発注日付は本日以降の日付を選択してください');
      return;
    }

    hideError();

    try {
      // 需要予測結果を取得
      const forecasts = await window.aivicApi.list(DEMAND_FORECAST_TABLE);
      const products = await window.aivicApi.list(PRODUCT_TABLE);

      if (!forecasts || !products) {
        renderProducts([]);
        return;
      }

      // 店舗・日付でフィルタリング
      const filteredForecasts = forecasts.filter(f => 
        f.店舗ID === storeId && 
        f.予測対象日 && 
        new Date(f.予測対象日).toDateString() === new Date(orderDate).toDateString()
      );

      // 商品情報とマージ
      let mergedProducts = filteredForecasts.map(forecast => {
        const product = products.find(p => p.商品ID === forecast.商品ID);
        if (!product) return null;

        return {
          ...product,
          ...forecast,
          現在在庫数量: Math.floor(Math.random() * 100), // サンプルデータ
          orderQuantity: forecast.推奨発注数量 || 0
        };
      }).filter(p => p && p.有効フラグ);

      // カテゴリフィルタ適用
      if (categoryFilter) {
        mergedProducts = mergedProducts.filter(p => p.商品カテゴリID === categoryFilter);
      }

      currentProducts = mergedProducts;
      selectedProducts.clear();
      renderProducts(currentProducts);

    } catch (error) {
      console.error('商品検索エラー:', error);
      showError('商品データの取得に失敗しました');
    }
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
  }

  function hideError() {
    container.querySelector('#error-message').classList.add('hidden');
  }

  // 発注確認ダイアログ表示
  function showConfirmDialog() {
    const selectedItems = currentProducts.filter(p => selectedProducts.has(p.商品ID));
    const totalQuantity = selectedItems.reduce((sum, p) => sum + (p.orderQuantity || 0), 0);
    const totalAmount = selectedItems.reduce((sum, p) => sum + (p.orderQuantity || 0) * (p.単価 || 0), 0);

    const content = `
      <p>以下の内容で発注を実行します。よろしいですか？</p>
      <ul style="margin: 16px 0; padding-left: 20px;">
        <li>選択商品数: ${selectedItems.length}件</li>
        <li>合計発注数量: ${totalQuantity.toLocaleString()}個</li>
        <li>合計発注金額: ¥${totalAmount.toLocaleString()}</li>
      </ul>
    `;

    container.querySelector('#confirm-content').innerHTML = content;
    container.querySelector('#confirm-dialog').classList.remove('hidden');
  }

  // 発注実行
  async function executeOrder() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const selectedItems = currentProducts.filter(p => selectedProducts.has(p.商品ID));

    try {
      for (const product of selectedItems) {
        const orderData = {
          店舗ID: storeId,
          商品ID: product.商品ID,
          需要予測結果ID: product.予測結果ID,
          発注日: new Date().toISOString(),
          納期予定日: new Date(Date.now() + (product.リードタイム日数 || 3) * 24 * 60 * 60 * 1000).toISOString(),
          発注数量: product.orderQuantity || 0,
          予測数量: product.予測数量 || 0,
          発注単価: product.単価 || 0,
          発注金額: (product.orderQuantity || 0) * (product.単価 || 0),
          発注方法: 'AI推奨採用',
          発注ステータス: '発注済',
          仕入先ID: product.仕入先ID,
          発注理由: 'AI需要予測に基づく発注',
          自動発注フラグ: false,
          作成者ID: 'current-user-id',
          更新者ID: 'current-user-id'
        };

        await window.aivicApi.save(ORDER_TABLE, orderData);
      }

      // 成功メッセージ
      alert('発注が正常に実行されました');

      // 画面リセット
      selectedProducts.clear();
      renderProducts(currentProducts);
      container.querySelector('#confirm-dialog').classList.add('hidden');

    } catch (error) {
      console.error('発注実行エラー:', error);
      showError('発注の実行に失敗しました');
    }
  }

  // 数量入力の検証
  function validateQuantity(input) {
    const value = input.value;
    const productId = input.dataset.id;

    // 空文字チェック
    if (value === '') {
      showError('発注数量を入力してください');
      return false;
    }

    // 数値チェック
    if (isNaN(value) || !/^\d+$/.test(value)) {
      showError('発注数量は数値を入力してください');
      input.value = 0;
      return false;
    }

    const numValue = parseInt(value);

    // 負の値チェック
    if (numValue < 0) {
      showError('発注数量は正の値を入力してください');
      input.value = 0;
      return false;
    }

    // ゼロチェック
    if (numValue === 0) {
      showError('発注数量は1以上の値を入力してください');
      return false;
    }

    // 上限値チェック（例：10000）
    if (numValue > 10000) {
      showError('発注数量は10,000以下で入力してください');
      input.value = 10000;
      return false;
    }

    hideError();

    // 商品データ更新
    const product = currentProducts.find(p => p.商品ID === productId);
    if (product) {
      product.orderQuantity = numValue;

      // 金額更新
      const amountCell = container.querySelector(`.order-amount[data-id="${productId}"]`);
      if (amountCell) {
        const amount = numValue * (product.単価 || 0);
        amountCell.textContent = `¥${amount.toLocaleString()}`;
      }

      updateSummary();
    }

    return true;
  }

  // イベントリスナー設定
  container.querySelector('#btn-search').addEventListener('click', searchProducts);

  container.querySelector('#btn-refresh').addEventListener('click', () => {
    searchProducts();
  });

  container.querySelector('#btn-select-all').addEventListener('click', () => {
    currentProducts.forEach(p => selectedProducts.add(p.商品ID));
    renderProducts(currentProducts);
  });

  container.querySelector('#btn-clear-selection').addEventListener('click', () => {
    selectedProducts.clear();
    renderProducts(currentProducts);
  });

  container.querySelector('#btn-execute-order').addEventListener('click', () => {
    if (selectedProducts.size === 0) {
      showError('発注する商品を選択してください');
      return;
    }
    showConfirmDialog();
  });

  container.querySelector('#btn-cancel-order').addEventListener('click', () => {
    container.querySelector('#confirm-dialog').classList.add('hidden');
  });

  container.querySelector('#btn-confirm-order').addEventListener('click', executeOrder);

  // イベントデリゲーション
  container.addEventListener('change', (e) => {
    // チェックボックス
    if (e.target.classList.contains('product-checkbox')) {
      const productId = e.target.dataset.id;
      if (e.target.checked) {
        selectedProducts.add(productId);
      } else {
        selectedProducts.delete(productId);
      }
      renderProducts(currentProducts);
    }

    // 数量入力
    if (e.target.classList.contains('quantity-input')) {
      validateQuantity(e.target);
    }
  });

  // 数量入力のblurイベント
  container.addEventListener('blur', (e) => {
    if (e.target.classList.contains('quantity-input')) {
      validateQuantity(e.target);
    }
  }, true);

  // 初期データ読み込み
  loadStores();
  loadCategories();
}

function(container, apiUrl, tables) {
  let currentData = [];
  let sortColumn = '';
  let sortDirection = 'asc';

  // 再描画関数の定義
  function renderRankingTable(data) {
    const tbody = container.querySelector('#ranking-tbody');
    if (!data || data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; color: var(--text-muted);">データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = data.map((row, index) => `
      <tr data-id="${row.id || index}">
        <td>${index + 1}</td>
        <td>${row.store_name || ''}</td>
        <td>${row.product_name || ''}</td>
        <td>${row.category || ''}</td>
        <td>${row.mape ? row.mape.toFixed(2) + '%' : 'N/A'}</td>
        <td>${row.rmse ? row.rmse.toFixed(2) : 'N/A'}</td>
        <td>${row.prediction_count || 0}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${row.id || index}">詳細分析</button>
        </td>
      </tr>
    `).join('');
  }

  // 初期データの読み込みと描画
  async function loadInitialData() {
    try {
      // 需要予測結果データを取得
      const predictionData = await window.aivicApi.list(4); // 需要予測結果テーブル
      if (predictionData) {
        // 精度データを生成（実際のシステムでは計算済みデータを取得）
        currentData = generateAccuracyData(predictionData);
        renderRankingTable(currentData);
        updateSummaryCards(currentData);
        drawCharts(currentData);
        checkAccuracyAlerts(currentData);
      }
    } catch (error) {
      showError('データの読み込みに失敗しました');
    }
  }

  // 精度データ生成（サンプル実装）
  function generateAccuracyData(predictionData) {
    const accuracyData = [];
    const storeMap = new Map();

    // 店舗データを取得
    const stores = tables[1]?.records || [];
    stores.forEach(store => {
      storeMap.set(store.id, store.store_name);
    });

    // 商品データを取得
    const products = tables[2]?.records || [];
    const productMap = new Map();
    products.forEach(product => {
      productMap.set(product.id, {
        name: product.product_name,
        category: product.product_category_id
      });
    });

    // 予測精度を計算（サンプル）
    predictionData.forEach((prediction, index) => {
      if (prediction.actual_quantity && prediction.predicted_quantity) {
        const error = Math.abs(prediction.actual_quantity - prediction.predicted_quantity);
        const mape = (error / prediction.actual_quantity) * 100;
        const rmse = Math.sqrt(Math.pow(error, 2));

        accuracyData.push({
          id: prediction.id,
          store_name: storeMap.get(prediction.store_id) || '不明店舗',
          product_name: productMap.get(prediction.product_id)?.name || '不明商品',
          category: productMap.get(prediction.product_id)?.category || '不明',
          mape: Math.min(mape, 100), // 上限100%
          rmse: rmse,
          prediction_count: 1
        });
      }
    });

    return accuracyData.slice(0, 50); // 上位50件
  }

  // サマリーカード更新
  function updateSummaryCards(data) {
    if (data.length === 0) return;

    const avgMape = data.reduce((sum, item) => sum + (item.mape || 0), 0) / data.length;
    const avgRmse = data.reduce((sum, item) => sum + (item.rmse || 0), 0) / data.length;

    container.querySelector('#avg-mape').textContent = avgMape.toFixed(2) + '%';
    container.querySelector('#avg-rmse').textContent = avgRmse.toFixed(2);
    container.querySelector('#target-products').textContent = data.length.toLocaleString();
  }

  // グラフ描画
  function drawCharts(data) {
    drawAccuracyTrendChart();
    drawPredictionVsActualChart();
  }

  function drawAccuracyTrendChart() {
    const canvas = container.querySelector('#accuracy-trend-chart');
    const ctx = canvas.getContext('2d');

    // キャンバスサイズ設定
    canvas.width = 800;
    canvas.height = 300;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // サンプルデータ
    const dates = ['1/1', '1/8', '1/15', '1/22', '1/29'];
    const mapeValues = [18.5, 16.2, 15.8, 14.9, 15.2];
    const rmseValues = [9.2, 8.8, 8.5, 8.1, 8.4];

    // グラフエリア設定
    const padding = 60;
    const graphWidth = canvas.width - padding * 2;
    const graphHeight = canvas.height - padding * 2;

    // 軸描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // MAPE線描画
    ctx.strokeStyle = '#00d4aa';
    ctx.lineWidth = 2;
    ctx.beginPath();
    mapeValues.forEach((value, index) => {
      const x = padding + (index / (mapeValues.length - 1)) * graphWidth;
      const y = canvas.height - padding - (value / 25) * graphHeight;
      if (index === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#d0e4ff';
    ctx.font = '14px Arial';
    ctx.fillText('MAPE推移', padding, 30);
  }

  function drawPredictionVsActualChart() {
    const canvas = container.querySelector('#prediction-vs-actual-chart');
    const ctx = canvas.getContext('2d');

    canvas.width = 800;
    canvas.height = 300;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // サンプルデータ
    const dates = ['1/1', '1/8', '1/15', '1/22', '1/29'];
    const predicted = [120, 135, 142, 138, 145];
    const actual = [115, 140, 138, 142, 148];

    const padding = 60;
    const graphWidth = canvas.width - padding * 2;
    const graphHeight = canvas.height - padding * 2;

    // 軸描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // 予測値線
    ctx.strokeStyle = '#ff6a00';
    ctx.lineWidth = 2;
    ctx.beginPath();
    predicted.forEach((value, index) => {
      const x = padding + (index / (predicted.length - 1)) * graphWidth;
      const y = canvas.height - padding - (value / 200) * graphHeight;
      if (index === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 実績値線
    ctx.strokeStyle = '#00d4aa';
    ctx.lineWidth = 2;
    ctx.beginPath();
    actual.forEach((value, index) => {
      const x = padding + (index / (actual.length - 1)) * graphWidth;
      const y = canvas.height - padding - (value / 200) * graphHeight;
      if (index === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#d0e4ff';
    ctx.font = '14px Arial';
    ctx.fillText('予測値', padding, 30);
    ctx.fillText('実績値', padding + 80, 30);
  }

  // アラートチェック
  function checkAccuracyAlerts(data) {
    const threshold = 20; // 精度閾値20%
    const poorAccuracyItems = data.filter(item => item.mape > threshold);

    const alertPanel = container.querySelector('#alert-panel');
    const alertMessage = container.querySelector('#alert-message');

    if (poorAccuracyItems.length > 0) {
      alertMessage.textContent = `${poorAccuracyItems.length}件の商品で精度閾値(${threshold}%)を超過しています`;
      alertPanel.classList.remove('hidden');
    } else {
      alertPanel.classList.add('hidden');
    }
  }

  // エラー表示
  function showError(message) {
    const errorPanel = container.querySelector('#error-message');
    const errorText = container.querySelector('#error-text');
    errorText.textContent = message;
    errorPanel.classList.remove('hidden');
  }

  function hideError() {
    container.querySelector('#error-message').classList.add('hidden');
  }

  // ソート機能
  function sortData(column) {
    if (sortColumn === column) {
      sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
    } else {
      sortColumn = column;
      sortDirection = 'asc';
    }

    currentData.sort((a, b) => {
      let aVal = a[column];
      let bVal = b[column];

      if (typeof aVal === 'string') {
        aVal = aVal.toLowerCase();
        bVal = bVal.toLowerCase();
      }

      if (sortDirection === 'asc') {
        return aVal > bVal ? 1 : -1;
      } else {
        return aVal < bVal ? 1 : -1;
      }
    });

    renderRankingTable(currentData);
  }

  // CSVエクスポート
  function exportCSV() {
    if (currentData.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['順位', '店舗名', '商品名', 'カテゴリ', 'MAPE(%)', 'RMSE', '予測回数'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...currentData.map((row, index) => [
        index + 1,
        `"${row.store_name || ''}"`,
        `"${row.product_name || ''}"`,
        `"${row.category || ''}"`,
        row.mape ? row.mape.toFixed(2) : '',
        row.rmse ? row.rmse.toFixed(2) : '',
        row.prediction_count || 0
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `prediction_accuracy_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 店舗選択肢の初期化
  function initializeStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    const stores = tables[1]?.records || [];

    stores.forEach(store => {
      const option = document.createElement('option');
      option.value = store.id;
      option.textContent = store.store_name;
      storeSelect.appendChild(option);
    });
  }

  // イベントリスナー登録

  // データ更新ボタン
  container.querySelector('#btn-refresh').addEventListener('click', async () => {
    hideError();
    await loadInitialData();
  });

  // フィルター適用ボタン
  container.querySelector('#btn-apply-filter').addEventListener('click', async () => {
    const period = container.querySelector('#period-select').value;
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;

    // フィルター適用ロジック（実装簡略化）
    let filteredData = [...currentData];

    if (storeId) {
      filteredData = filteredData.filter(item => item.store_id === storeId);
    }

    if (category) {
      filteredData = filteredData.filter(item => item.category === category);
    }

    renderRankingTable(filteredData);
    updateSummaryCards(filteredData);
  });

  // レポート出力ボタン
  container.querySelector('#btn-export-report').addEventListener('click', () => {
    try {
      exportCSV();
    } catch (error) {
      showError('レポート出力に失敗しました');
    }
  });

  // CSVエクスポートボタン
  container.querySelector('#btn-export-csv').addEventListener('click', exportCSV);

  // アラート閉じるボタン
  container.querySelector('#btn-dismiss-alert').addEventListener('click', () => {
    container.querySelector('#alert-panel').classList.add('hidden');
  });

  // エラー再試行ボタン
  container.querySelector('#btn-retry').addEventListener('click', async () => {
    hideError();
    await loadInitialData();
  });

  // イベントデリゲーション
  container.addEventListener('click', async (e) => {
    // ソート機能
    const sortable = e.target.closest('.sortable');
    if (sortable) {
      const column = sortable.dataset.sort;
      sortData(column);
      return;
    }

    // 詳細分析ボタン
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      // 詳細分析画面への遷移（実装例）
      window.showScreen('scr-1778591838939'); // 需要予測管理画面
      return;
    }

    // アラート詳細確認ボタン
    const viewDetailsBtn = e.target.closest('#btn-view-details');
    if (viewDetailsBtn) {
      window.showScreen('scr-1778591838939'); // 需要予測管理画面
      return;
    }
  });

  // 初期化実行
  initializeStoreOptions();
  loadInitialData();
}

function(container, apiUrl, tables) {
  // 店舗データの読み込み
  const storeSelect = container.querySelector('#target-store');
  const storeTable = tables.find(t => t.tableName === '店舗マスタ');
  if (storeTable && storeTable.records) {
    storeTable.records.forEach(store => {
      if (store.有効フラグ) {
        const option = document.createElement('option');
        option.value = store.店舗ID;
        option.textContent = `${store.店舗コード} - ${store.店舗名}`;
        storeSelect.appendChild(option);
      }
    });
  }

  // 学習率スライダーの値表示更新
  const learningRateSlider = container.querySelector('#learning-rate');
  const learningRateValue = container.querySelector('#learning-rate-value');
  learningRateSlider.addEventListener('input', function() {
    learningRateValue.textContent = this.value;
  });

  // 全選択チェックボックスの処理
  const selectAllData = container.querySelector('#select-all-data');
  const dataSourceItems = container.querySelectorAll('.data-source-item');

  selectAllData.addEventListener('change', function() {
    dataSourceItems.forEach(item => {
      item.checked = this.checked;
    });
  });

  dataSourceItems.forEach(item => {
    item.addEventListener('change', function() {
      const allChecked = Array.from(dataSourceItems).every(item => item.checked);
      const someChecked = Array.from(dataSourceItems).some(item => item.checked);
      selectAllData.checked = allChecked;
      selectAllData.indeterminate = someChecked && !allChecked;
    });
  });

  // 重み付け設定の合計値計算
  const weightInputs = container.querySelectorAll('.weight-input');
  const weightTotal = container.querySelector('#weight-total');

  function updateWeightTotal() {
    let total = 0;
    weightInputs.forEach(input => {
      total += parseInt(input.value) || 0;
    });
    weightTotal.textContent = total;
    weightTotal.className = total === 100 ? '' : 'error';
    return total;
  }

  weightInputs.forEach(input => {
    input.addEventListener('input', updateWeightTotal);
  });

  // バリデーション関数
  function showError(fieldId, message) {
    const errorElement = container.querySelector(`#${fieldId}-error`);
    if (errorElement) {
      errorElement.textContent = message;
      errorElement.classList.add('show');
    }
  }

  function hideError(fieldId) {
    const errorElement = container.querySelector(`#${fieldId}-error`);
    if (errorElement) {
      errorElement.classList.remove('show');
    }
  }

  function validateForm() {
    let isValid = true;

    // モデル名チェック
    const modelName = container.querySelector('#model-name').value.trim();
    if (!modelName) {
      showError('model-name', 'モデル名を入力してください');
      isValid = false;
    } else {
      hideError('model-name');
    }

    // 対象店舗チェック
    const targetStore = container.querySelector('#target-store').value;
    if (!targetStore) {
      showError('target-store', '対象店舗を選択してください');
      isValid = false;
    } else {
      hideError('target-store');
    }

    // 商品カテゴリチェック
    const selectedCategories = container.querySelectorAll('#product-categories input[type="checkbox"]:checked');
    if (selectedCategories.length === 0) {
      showError('product-categories', '対象商品カテゴリを選択してください');
      isValid = false;
    } else {
      hideError('product-categories');
    }

    // 学習期間チェック
    const startDate = container.querySelector('#learning-start-date').value;
    const endDate = container.querySelector('#learning-end-date').value;

    if (!startDate || !endDate) {
      showError('learning-start-date', '学習期間を設定してください');
      isValid = false;
    } else if (new Date(startDate) > new Date(endDate)) {
      showError('learning-start-date', '開始日は終了日より前の日付を設定してください');
      isValid = false;
    } else if (new Date(startDate) > new Date() || new Date(endDate) > new Date()) {
      showError('learning-start-date', '学習期間に未来の日付は設定できません');
      isValid = false;
    } else {
      hideError('learning-start-date');
      hideError('learning-end-date');
    }

    // 予測期間チェック
    const predictionPeriod = container.querySelector('input[name="prediction-period"]:checked');
    if (!predictionPeriod) {
      showError('prediction-period', '予測期間を選択してください');
      isValid = false;
    } else {
      hideError('prediction-period');
    }

    // データソースチェック
    const selectedDataSources = container.querySelectorAll('.data-source-item:checked');
    if (selectedDataSources.length === 0) {
      showError('data-sources', 'データソースを選択してください');
      isValid = false;
    } else {
      hideError('data-sources');
    }

    // アルゴリズムチェック
    const algorithm = container.querySelector('#algorithm').value;
    if (!algorithm) {
      showError('algorithm', 'アルゴリズムを選択してください');
      isValid = false;
    } else {
      hideError('algorithm');
    }

    // 季節性パラメータチェック
    const seasonalParam = container.querySelector('#seasonal-param').value;
    if (seasonalParam && isNaN(parseFloat(seasonalParam))) {
      showError('seasonal-param', '数値を入力してください');
      isValid = false;
    } else {
      hideError('seasonal-param');
    }

    // 精度目標値チェック
    const accuracyTarget = container.querySelector('#accuracy-target').value;
    if (accuracyTarget && (parseInt(accuracyTarget) < 0 || parseInt(accuracyTarget) > 100)) {
      showError('accuracy-target', '0から100の範囲で入力してください');
      isValid = false;
    } else {
      hideError('accuracy-target');
    }

    // 重み付け合計チェック
    const weightSum = updateWeightTotal();
    if (weightSum !== 100) {
      showError('weight', '重み付けの合計値は100%にしてください');
      isValid = false;
    } else {
      hideError('weight');
    }

    return isValid;
  }

  // 保存ボタンのイベントリスナー
  container.querySelector('#btn-save').addEventListener('click', async function() {
    if (!validateForm()) {
      return;
    }

    // 既存モデル名チェック
    const modelName = container.querySelector('#model-name').value.trim();
    const existingModels = await window.aivicApi.list(0);
    if (existingModels && existingModels.some(model => model.モデル名 === modelName)) {
      showError('model-name', 'このモデル名は既に使用されています');
      return;
    }

    // フォームデータ収集
    const formData = {
      モデル名: modelName,
      対象店舗ID: container.querySelector('#target-store').value,
      対象商品カテゴリ: Array.from(container.querySelectorAll('#product-categories input[type="checkbox"]:checked')).map(cb => cb.value).join(','),
      学習期間開始日: container.querySelector('#learning-start-date').value,
      学習期間終了日: container.querySelector('#learning-end-date').value,
      予測期間: container.querySelector('input[name="prediction-period"]:checked').value,
      使用データソース: Array.from(container.querySelectorAll('.data-source-item:checked')).map(cb => cb.value).join(','),
      アルゴリズム: container.querySelector('#algorithm').value,
      学習率: parseFloat(container.querySelector('#learning-rate').value),
      季節性調整パラメータ: parseFloat(container.querySelector('#seasonal-param').value) || 1.0,
      モデル精度目標値: parseInt(container.querySelector('#accuracy-target').value) || 85,
      異常値除外設定: container.querySelector('#exclude-outliers').checked,
      重み付け設定: JSON.stringify({
        sales: parseInt(container.querySelector('.weight-input[data-factor="sales"]').value),
        weather: parseInt(container.querySelector('.weight-input[data-factor="weather"]').value),
        event: parseInt(container.querySelector('.weight-input[data-factor="event"]').value),
        season: parseInt(container.querySelector('.weight-input[data-factor="season"]').value)
      }),
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: 'current-user-id'
    };

    const saved = await window.aivicApi.save(0, formData);
    if (saved) {
      alert('モデルが正常に作成されました');
      // フォームリセット
      container.querySelector('#model-name').value = '';
      container.querySelector('#target-store').selectedIndex = 0;
      container.querySelectorAll('#product-categories input[type="checkbox"]').forEach(cb => cb.checked = false);
      container.querySelector('#learning-start-date').value = '';
      container.querySelector('#learning-end-date').value = '';
      container.querySelectorAll('input[name="prediction-period"]').forEach(rb => rb.checked = false);
      container.querySelectorAll('.data-source-item').forEach(cb => cb.checked = false);
      container.querySelector('#select-all-data').checked = false;
      container.querySelector('#algorithm').selectedIndex = 0;
      container.querySelector('#learning-rate').value = 0.01;
      learningRateValue.textContent = '0.01';
      container.querySelector('#seasonal-param').value = 1.0;
      container.querySelector('#accuracy-target').value = 85;
      container.querySelector('#exclude-outliers').checked = false;
      weightInputs.forEach((input, index) => {
        input.value = [40, 20, 20, 20][index];
      });
      updateWeightTotal();
    }
  });

  // テストボタン
  container.querySelector('#btn-test').addEventListener('click', function() {
    if (validateForm()) {
      window.showScreen('scr-1778591999045'); // モデルテスト機能画面
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', function() {
    window.showScreen('scr-1778591780173'); // ダッシュボード画面
  });

  // 初期化時の重み付け合計計算
  updateWeightTotal();
}

