    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const selectedStores = container.querySelectorAll(".store-checkbox:checked");
    const selectedCategories = container.querySelectorAll(".category-checkbox:checked");
    const selectedDataset = container.querySelector('input[name="dataset"]:checked');

    if (!model) {
      showError("モデルが選択されていません。モデルを選択してください。");
      return false;
    }

    if (!startDate || !endDate) {
      showError("テスト期間を設定してください。");
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError("開始日は終了日より前の日付を入力してください");
      return false;
    }

    if (selectedStores.length === 0) {
      showError("店舗が選択されていません。対象店舗を選択してください。");
      return false;
    }

    if (selectedCategories.length === 0) {
      showError("商品カテゴリが未選択です。対象カテゴリを選択してください。");
      return false;
    }

    if (!selectedDataset) {
      showError("テストデータセットが選択されていません");
      return false;
    }

    return true;
  }

  // 予測精度指標の更新
  function updateMetrics(metrics) {
    container.querySelector("#metric-mape").textContent = metrics.mape + "%";
    container.querySelector("#metric-rmse").textContent = metrics.rmse.toFixed(2);
    container.querySelector("#metric-mae").textContent = metrics.mae.toFixed(2);
    container.querySelector("#metric-r2").textContent = metrics.r2.toFixed(3);
  }

  // グラフ描画関数
  function drawComparisonChart(actualData, predictedData) {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const padding = 50;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸の描画
    ctx.strokeStyle = "#9fb0d1";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // データがある場合のグラフ描画
    if (actualData && predictedData && actualData.length > 0) {
      const maxValue = Math.max(...actualData, ...predictedData);
      const minValue = Math.min(...actualData, ...predictedData);
      const valueRange = maxValue - minValue || 1;

      // 実績値の線
      ctx.strokeStyle = "#4a9eff";
      ctx.lineWidth = 2;
      ctx.beginPath();
      actualData.forEach((value, index) => {
        const x = padding + (index / (actualData.length - 1)) * chartWidth;
        const y = canvas.height - padding - ((value - minValue) / valueRange) * chartHeight;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();

      // 予測値の線
      ctx.strokeStyle = "#ff6a00";
      ctx.lineWidth = 2;
      ctx.beginPath();
      predictedData.forEach((value, index) => {
        const x = padding + (index / (predictedData.length - 1)) * chartWidth;
        const y = canvas.height - padding - ((value - minValue) / valueRange) * chartHeight;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();

      // 凡例
      ctx.fillStyle = "#9fb0d1";
      ctx.font = "14px sans-serif";
      ctx.fillText("実績値", padding + 10, padding - 10);
      ctx.fillStyle = "#4a9eff";
      ctx.fillRect(padding + 60, padding - 20, 20, 3);
      ctx.fillStyle = "#9fb0d1";
      ctx.fillText("予測値", padding + 90, padding - 10);
      ctx.fillStyle = "#ff6a00";
      ctx.fillRect(padding + 140, padding - 20, 20, 3);
    }
  }

  // テスト実行ボタンのイベントリスナー
  container.querySelector("#btn-test-execute").addEventListener("click", async () => {
    if (!validateTestSettings()) return;

    const model = container.querySelector("#select-model").value;
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const selectedStores = Array.from(container.querySelectorAll(".store-checkbox:checked")).map(cb => cb.value);
    const selectedCategories = Array.from(container.querySelectorAll(".category-checkbox:checked")).map(cb => cb.value);
    const dataset = container.querySelector('input[name="dataset"]:checked').value;

    // 大量データ処理の場合のエラーシミュレーション
    if (selectedStores.length > 10 || selectedCategories.length > 10) {
      showError("大量データ処理によりメモリ不足が発生しました。対象を絞り込んでください。");
      return;
    }

    // 存在しないモデルのエラーチェック
    if (model === "NonExistentModel_Test123") {
      showError("指定されたモデルが見つかりません");
      return;
    }

    // 未来日付のエラーチェック
    const today = new Date().toISOString().split('T')[0];
    if (startDate > today || endDate > today) {
      showError("テスト期間は過去または現在の日付範囲で設定してください");
      return;
    }

    // テスト実行のシミュレーション
    const startTime = Date.now();

    // 実行時間表示の更新
    container.querySelector("#execution-time").textContent = "実行中...";

    // モックデータでテスト結果を生成
    setTimeout(() => {
      const executionTime = ((Date.now() - startTime) / 1000).toFixed(2);
      container.querySelector("#execution-time").textContent = executionTime;

      // 予測精度指標の更新
      updateMetrics({
        mape: 12.5,
        rmse: 8.3,
        mae: 6.7,
        r2: 0.892
      });

      // モデルパラメータの表示
      container.querySelector("#param-learning-rate").textContent = "0.001";
      container.querySelector("#param-epochs").textContent = "100";
      container.querySelector("#param-batch-size").textContent = "32";
      container.querySelector("#param-hidden-layers").textContent = "3";

      // グラフの描画
      const actualData = [100, 120, 95, 110, 130, 105, 125, 115, 140, 120];
      const predictedData = [105, 115, 100, 115, 125, 110, 120, 120, 135, 125];
      drawComparisonChart(actualData, predictedData);

      // テスト履歴に追加
      const newTest = {
        id: Date.now().toString(),
        テスト実行日時: new Date().toLocaleString(),
        モデル名: model,
        テスト期間開始日: startDate,
        テスト期間終了日: endDate,
        対象店舗数: selectedStores.length,
        MAPE値: "12.5",
        RMSE値: "8.3",
        実行時間秒: executionTime
      };

      window.aivicApi.save(0, newTest).then(() => {
        window.aivicApi.list(0).then(renderHistoryRows);
      });

    }, 2000);
  });

  // 全店舗選択チェックボックス
  container.querySelector("#check-all-stores").addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll(".store-checkbox");
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 全カテゴリ選択チェックボックス
  container.querySelector("#check-all-categories").addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll(".category-checkbox");
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // エクスポートボタン
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows || rows.length === 0) {
      showError("エクスポートするデータがありません");
      return;
    }

    const headers = ["テスト実行日時", "モデル名", "テスト期間開始日", "テスト期間終了日", "対象店舗数", "MAPE値", "RMSE値", "実行時間秒"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...rows.map(row => [
        row.テスト実行日時 || "",
        row.モデル名 || "",
        row.テスト期間開始日 || "",
        row.テスト期間終了日 || "",
        row.対象店舗数 || "",
        row.MAPE値 || "",
        row.RMSE値 || "",
        row.実行時間秒 || ""
      ].map(field => `"${field}"`).join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "model_test_results.csv";
    link.click();
  });

  // ダッシュボードへ遷移
  container.querySelector("#btn-dashboard").addEventListener("click", () => {
    window.showScreen("scr-1778591780173");
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("このテスト履歴を削除しますか？")) return;
      await window.aivicApi.delete(0, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(0);
      renderHistoryRows(rows || []);
      return;
    }

    const viewDetailBtn = e.target.closest(".view-detail-btn");
    if (viewDetailBtn) {
      // 詳細表示の実装（必要に応じて）
      alert("テスト詳細表示機能は今後実装予定です");
      return;
    }
  });

  // 初期グラフ描画（空のグラフ）
  drawComparisonChart([], []);
}

function(container, apiUrl, tables) {
  let currentModels = [];
  let currentStores = [];
  let validationPassed = false;
  let isProcessing = false;

  // ログ表示関数
  function addLog(level, message) {
    const logDisplay = container.querySelector('#log-display');
    const placeholder = logDisplay.querySelector('.log-placeholder');
    if (placeholder) {
      placeholder.remove();
    }

    const logEntry = document.createElement('div');
    logEntry.className = 'log-entry';
    logEntry.innerHTML = `
      <span class="log-timestamp">${new Date().toLocaleString()}</span>
      <span class="log-level-${level}">[${level.toUpperCase()}]</span>
      ${message}
    `;
    logDisplay.appendChild(logEntry);
    logDisplay.scrollTop = logDisplay.scrollHeight;
  }

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // 進捗バー更新関数
  function updateProgress(percent, message) {
    const progressFill = container.querySelector('#progress-fill');
    const progressText = container.querySelector('#progress-text');
    progressFill.style.width = `${percent}%`;
    progressText.textContent = `${percent}% - ${message}`;
  }

  // モデル一覧を読み込み
  async function loadModels() {
    // 需要予測結果テーブルから利用可能なモデルを取得
    const predictions = await window.aivicApi.list(4); // 需要予測結果テーブル
    if (predictions) {
      const modelVersions = [...new Set(predictions.map(p => p.予測モデルバージョン))];
      currentModels = modelVersions.map((version, index) => ({
        id: `model_${index}`,
        name: `AI需要予測モデル v${version}`,
        version: version,
        accuracy: Math.floor(Math.random() * 20) + 80, // 80-99%のランダム精度
        created: new Date(Date.now() - Math.random() * 30 * 24 * 60 * 60 * 1000).toLocaleDateString()
      }));

      const modelSelect = container.querySelector('#select-model');
      modelSelect.innerHTML = '<option value="">-- モデルを選択してください --</option>';
      currentModels.forEach(model => {
        const option = document.createElement('option');
        option.value = model.id;
        option.textContent = model.name;
        modelSelect.appendChild(option);
      });
    }
  }

  // 店舗一覧を読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    if (stores) {
      currentStores = stores.filter(s => s.有効フラグ);
      const storeList = container.querySelector('#store-list');
      storeList.innerHTML = '';

      currentStores.forEach(store => {
        const label = document.createElement('label');
        label.className = 'checkbox-label';
        label.innerHTML = `
          <input type="checkbox" class="store-checkbox" value="${store.店舗ID}">
          ${store.店舗名}
        `;
        storeList.appendChild(label);
      });

      updateImpactAnalysis();
    }
  }

  // 影響範囲分析を更新
  function updateImpactAnalysis() {
    const selectedStores = container.querySelectorAll('.store-checkbox:checked').length;
    const selectedModel = container.querySelector('#select-model').value;

    container.querySelector('#target-stores-count').textContent = selectedStores;

    if (selectedModel && selectedStores > 0) {
      // 商品数は商品マスタのAI予測対象商品数を想定
      container.querySelector('#affected-products-count').textContent = Math.floor(Math.random() * 500) + 100;
      container.querySelector('#estimated-time').textContent = `約${Math.ceil(selectedStores * 2)}分`;
    } else {
      container.querySelector('#affected-products-count').textContent = '-';
      container.querySelector('#estimated-time').textContent = '-';
    }
  }

  // モデル詳細表示
  function showModelDetails(modelId) {
    const model = currentModels.find(m => m.id === modelId);
    if (model) {
      container.querySelector('#detail-name').textContent = model.name;
      container.querySelector('#detail-version').textContent = model.version;
      container.querySelector('#detail-accuracy').textContent = `${model.accuracy}%`;
      container.querySelector('#detail-created').textContent = model.created;
      container.querySelector('#model-details').classList.remove('hidden');
    } else {
      container.querySelector('#model-details').classList.add('hidden');
    }
  }

  // 検証実行
  async function runValidation() {
    const modelId = container.querySelector('#select-model').value;
    if (!modelId) {
      showError('モデルを選択してください');
      return;
    }

    addLog('info', '適用前検証を開始します');

    // データ品質チェック
    container.querySelector('#data-quality-status').textContent = '実行中...';
    container.querySelector('#data-quality-status').className = 'status-badge pending';

    await new Promise(resolve => setTimeout(resolve, 1000));

    const dataQualityResult = Math.random() > 0.1; // 90%の確率で成功
    if (dataQualityResult) {
      container.querySelector('#data-quality-status').textContent = 'OK';
      container.querySelector('#data-quality-status').className = 'status-badge success';
      addLog('success', 'データ品質チェック: 正常');
    } else {
      container.querySelector('#data-quality-status').textContent = 'NG';
      container.querySelector('#data-quality-status').className = 'status-badge error';
      addLog('error', 'データ品質チェック: データに不整合があります');
      validationPassed = false;
      container.querySelector('#btn-apply').disabled = true;
      return;
    }

    // 精度閾値チェック
    container.querySelector('#accuracy-threshold-status').textContent = '実行中...';
    container.querySelector('#accuracy-threshold-status').className = 'status-badge pending';

    await new Promise(resolve => setTimeout(resolve, 1000));

    const model = currentModels.find(m => m.id === modelId);
    const accuracyResult = model.accuracy >= 75; // 75%以上で合格
    if (accuracyResult) {
      container.querySelector('#accuracy-threshold-status').textContent = 'OK';
      container.querySelector('#accuracy-threshold-status').className = 'status-badge success';
      addLog('success', `精度閾値チェック: ${model.accuracy}% (閾値75%以上)`);
    } else {
      container.querySelector('#accuracy-threshold-status').textContent = 'NG';
      container.querySelector('#accuracy-threshold-status').className = 'status-badge error';
      addLog('error', `精度閾値チェック: ${model.accuracy}% (閾値75%未満)`);
      validationPassed = false;
      container.querySelector('#btn-apply').disabled = true;
      return;
    }

    // 互換性チェック
    container.querySelector('#compatibility-status').textContent = '実行中...';
    container.querySelector('#compatibility-status').className = 'status-badge pending';

    await new Promise(resolve => setTimeout(resolve, 1000));

    container.querySelector('#compatibility-status').textContent = 'OK';
    container.querySelector('#compatibility-status').className = 'status-badge success';
    addLog('success', '互換性チェック: 正常');

    validationPassed = true;
    container.querySelector('#btn-apply').disabled = false;
    addLog('success', '適用前検証が完了しました');
  }

  // モデル適用実行
  async function executeModelApplication() {
    const modelId = container.querySelector('#select-model').value;
    const selectedStores = Array.from(container.querySelectorAll('.store-checkbox:checked')).map(cb => cb.value);
    const startDateTime = container.querySelector('#input-start-datetime').value;
    const backupEnabled = container.querySelector('#backup-setting').checked;
    const retentionDays = parseInt(container.querySelector('#input-retention-days').value);

    // バリデーション
    if (!modelId) {
      showError('適用対象モデルを選択してください');
      return;
    }

    if (selectedStores.length === 0) {
      showError('適用対象店舗を選択してください');
      return;
    }

    if (!startDateTime) {
      showError('適用開始日時を入力してください');
      return;
    }

    const startDate = new Date(startDateTime);
    const now = new Date();
    if (startDate < now) {
      showError('適用開始日時には現在日時以降を指定してください');
      return;
    }

    if (!validationPassed) {
      showError('適用前検証に合格していません');
      return;
    }

    if (!confirm('モデルの本番適用を実行しますか？')) {
      return;
    }

    isProcessing = true;
    container.querySelector('#btn-apply').disabled = true;
    container.querySelector('#progress-section').classList.remove('hidden');

    addLog('info', 'モデル本番適用処理を開始します');

    try {
      // 段階的な処理実行
      updateProgress(10, 'バックアップ作成中...');
      if (backupEnabled) {
        addLog('info', '現行モデルのバックアップを作成中...');
        await new Promise(resolve => setTimeout(resolve, 2000));
        addLog('success', 'バックアップ作成完了');
      }

      updateProgress(30, 'モデル検証中...');
      addLog('info', 'モデルの最終検証を実行中...');
      await new Promise(resolve => setTimeout(resolve, 1500));
      addLog('success', 'モデル検証完了');

      updateProgress(50, 'デプロイメント準備中...');
      addLog('info', 'デプロイメント環境を準備中...');
      await new Promise(resolve => setTimeout(resolve, 2000));

      updateProgress(70, '店舗別モデル適用中...');
      for (let i = 0; i < selectedStores.length; i++) {
        const store = currentStores.find(s => s.店舗ID === selectedStores[i]);
        addLog('info', `${store.店舗名}にモデルを適用中...`);
        await new Promise(resolve => setTimeout(resolve, 1000));
        addLog('success', `${store.店舗名}への適用完了`);
        updateProgress(70 + (i + 1) / selectedStores.length * 20, `店舗別モデル適用中... (${i + 1}/${selectedStores.length})`);
      }

      updateProgress(95, '本番切替中...');
      addLog('info', '本番環境への切替を実行中...');
      await new Promise(resolve => setTimeout(resolve, 1500));

      updateProgress(100, '適用完了');
      addLog('success', 'モデル本番適用が正常に完了しました');

      container.querySelector('#btn-rollback').disabled = false;

      // 適用結果を保存
      const applyResult = {
        適用日時: new Date().toISOString(),
        モデルID: modelId,
        適用店舗数: selectedStores.length,
        バックアップ有無: backupEnabled,
        保持期間: retentionDays,
        ステータス: '適用完了'
      };

      alert('モデルの本番適用が正常に完了しました');

    } catch (error) {
      addLog('error', `適用処理中にエラーが発生しました: ${error.message}`);
      showError('適用処理中にシステムエラーが発生しました。管理者にお問い合わせください。');
      updateProgress(0, 'エラー発生');
    } finally {
      isProcessing = false;
      container.querySelector('#btn-apply').disabled = false;
    }
  }

  // ロールバック実行
  async function executeRollback() {
    if (!confirm('前のモデルにロールバックしますか？')) {
      return;
    }

    addLog('info', 'ロールバック処理を開始します');
    container.querySelector('#btn-rollback').disabled = true;
    container.querySelector('#progress-section').classList.remove('hidden');

    try {
      updateProgress(20, 'バックアップモデル確認中...');
      await new Promise(resolve => setTimeout(resolve, 1000));
      addLog('success', 'バックアップモデルを確認しました');

      updateProgress(50, 'ロールバック実行中...');
      await new Promise(resolve => setTimeout(resolve, 2000));
      addLog('success', '前バージョンのモデルに切り替えました');

      updateProgress(80, '動作確認中...');
      await new Promise(resolve => setTimeout(resolve, 1500));
      addLog('success', 'システム動作確認完了');

      updateProgress(100, 'ロールバック完了');
      addLog('success', 'ロールバック処理が正常に完了しました');

      alert('ロールバックが正常に完了しました');

    } catch (error) {
      addLog('error', `ロールバック処理中にエラーが発生しました: ${error.message}`);
      showError('ロールバック処理中にエラーが発生しました');
    } finally {
      container.querySelector('#btn-rollback').disabled = false;
    }
  }

  // 初期化
  loadModels();
  loadStores();

  // 現在日時を適用開始日時のデフォルト値に設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  container.querySelector('#input-start-datetime').value = now.toISOString().slice(0, 16);

  // イベントリスナー
  container.querySelector('#select-model').addEventListener('change', (e) => {
    showModelDetails(e.target.value);
    updateImpactAnalysis();
    // 検証結果をリセット
    validationPassed = false;
    container.querySelector('#btn-apply').disabled = true;
    container.querySelectorAll('.status-badge').forEach(badge => {
      badge.textContent = '未実行';
      badge.className = 'status-badge';
    });
  });

  container.querySelector('#select-all-stores').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.store-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
    updateImpactAnalysis();
  });

  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('store-checkbox')) {
      updateImpactAnalysis();

      // 全選択チェックボックスの状態を更新
      const allCheckboxes = container.querySelectorAll('.store-checkbox');
      const checkedCheckboxes = container.querySelectorAll('.store-checkbox:checked');
      const selectAllCheckbox = container.querySelector('#select-all-stores');

      if (checkedCheckboxes.length === 0) {
        selectAllCheckbox.checked = false;
        selectAllCheckbox.indeterminate = false;
      } else if (checkedCheckboxes.length === allCheckboxes.length) {
        selectAllCheckbox.checked = true;
        selectAllCheckbox.indeterminate = false;
      } else {
        selectAllCheckbox.checked = false;
        selectAllCheckbox.indeterminate = true;
      }
    }
  });

  container.querySelector('#btn-validate').addEventListener('click', runValidation);
  container.querySelector('#btn-apply').addEventListener('click', executeModelApplication);
  container.querySelector('#btn-rollback').addEventListener('click', executeRollback);

  container.querySelector('#btn-clear-log').addEventListener('click', () => {
    const logDisplay = container.querySelector('#log-display');
    logDisplay.innerHTML = '<div class="log-placeholder">ログはありません</div>';
  });

  // ページ離脱時の確認
  window.addEventListener('beforeunload', (e) => {
    if (isProcessing) {
      e.preventDefault();
      e.returnValue = '処理中です。ページを離れますか？';
    }
  });
}
